#include "stdafx.h"

// =============================================================================
//  (th4) DUTCH localization (LANG_NL). Mirrors LocalizationDA.cpp structure.
//
//  ENCODING: raw CP1252 bytes (latin-1 on disk). Dutch needs only two marks and
//  both are in CP1252:
//        0xEB e-diaeresis (malienkolder, reeel)   0xEF i-diaeresis
//        0xE9 e-acute     (een)                   0xFC u-diaeresis
//  GLYPH COVERAGE differs by font, and this was measured, not assumed:
//    * MID and BIG have their OWN frames for E-acute / E-diaeresis / I-diaeresis
//      / U-diaeresis (67 / 69 / 73 / 86) -- they render correctly.
//    * SMALL has NO accents at all: every E-grave/acute/circumflex/diaeresis
//      shares frame 5 with plain "e", likewise i-forms at 9 and u-forms at 21.
//      So in the small font an accent silently folds to its base letter.
//  That is acceptable and is exactly what PT and DE already do (both keep real
//  accent bytes in their overlay tables). The fold is READABLE and never blank,
//  so accents are kept rather than pre-folded the way Danish had to.
//  No .mor is mounted for NL: it simply reuses the Portuguese font path. See the
//  LANG_NL case in Localization.cpp.
//
//  RULES:
//    * Any table may use the real accented bytes above -- MID/BIG show them,
//      SMALL folds them to the base letter.
//    * A missing key falls back to ENGLISH, which renders correctly in the Latin
//      fonts. Unlike Bulgarian, a partial Dutch translation is safe to ship and
//      degrades to readable English rather than to blanks.
//    * \xNN followed by a literal hex digit needs a "" break (greedy-hex trap).
//
//  ---- STATUS -------------------------------------------------------------
//  SCAFFOLD ONLY. Every table holds a lone placeholder => 0 rows => the whole
//  UI falls back to English. This is a valid, shippable state: selecting
//  language 14 gives a working English build with the Dutch path active.
//  Fill tables in batches; keys must byte-exactly match the English source
//  literal or the row is silently ignored.
// =============================================================================

struct UiStr  { const char* en; const char* nl; }; // .nl column holds the NL text
struct IdxStr { int index; const char* nl; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

// -----------------------------------------------------------------------------
//  A lone { 0, 0 } placeholder => count 0 => English fallback.
// -----------------------------------------------------------------------------

// (th4) Main UI table. COMPLETE: 1154 rows.
// Keys match the English source BYTE-EXACTLY: a stray trailing space silently
// drops the row (two NL_Menu rows were lost that way before the check was added).
// The *_one / *_few / *_many keys are PLURAL FORMS. Russian needs three (1 / 2-4 /
// 5+); Dutch has only singular and plural, so _few and _many carry the same word.
// Many rows are LINE FRAGMENTS the tooltip stacks into one sentence -- they keep
// their own breaks and stay short enough for the panel width. The stat-column
// abbreviations (kra/beh/mag/vit, slagwrst.) are deliberately short for the same
// reason. %c pairs are colour-control bytes wrapping a number: their order and
// count are preserved exactly, and the Dutch is shaped around them.
// The weapon-type lines "(+70%% to undead, -50%% to beasts)" and the element lines
// are GENERATED from the key list, so a number can never drift from its row.
// Class names are checked against NL_Menu before emitting -- the character sheet
// and the creation menu must show the same word.
