// (th4) Unique item names. COMPLETE: 2957 rows.
//   * 740 SINGLE-TOKEN names kept AS-IS. They are coined proper names (Absolver,
//     Annihilus, Akaviri) and Dutch uses the Latin alphabet, so an untouched name
//     renders correctly and still reads as a name -- the same call made for
//     NL_IceAge. Bulgarian had to transliterate all 740 because Latin drew BLANK
//     in the Cyrillic fonts; here they cost nothing. Emitted explicitly rather
//     than skipped so the choice is visible instead of implied.
//   * "X of Y" -> "X van Y". Bulgarian needed the DEFINITE form for Y (the slot
//     Russian fills with the genitive); Dutch takes the bare noun, and only the
//     "the <noun>" family carries an article, chosen per gender (de/het).
//   * "<Name>'s X" -> "<Name>s X". Dutch has a real possessive -s, so the owner
//     stays in FRONT; Bulgarian had to move it behind the noun.
//   * the adjective+noun names are written out: a generator would have needed more
//     vocabulary entries (910) than there are rows (1087). Dutch compounds by
//     direct concatenation, so most become single words -- Bloodmoon Talisman ->
//     "Bloedmaantalisman", Hellforge Hammer -> "Helsmidsehamer".
// Latin and other foreign names (Mors Indecepta, Alma Negra, Qovlu Sawarim) are
// left AS-IS: they are names in the English too.
// Head nouns are shared with NL_BaseItem, so a unique and a base item never disagree.
// The "cancelled" and "unused" engine markers are kept verbatim.
