// (th4) Item affix PREFIXES. Two deliberate Dutch decisions:
//  1. ADJECTIVE INFLECTION. Dutch adjectives inflect for gender: "scherpe bijl"
//     (de-word) but "scherp zwaard" (indefinite het-word). The engine splices
//     "<prefix> <name>" with no gender knowledge, so one form must serve both. The
//     INFLECTED -e form is used throughout: de-words are the large majority, so it is
//     right far more often than the bare form would be. Bulgarian solved this with a
//     gender table; that is not possible here because the affix table cannot see the
//     base item it will be joined to.
//  2. POSSESSIVES STAY PREFIXED, unlike Bulgarian. Dutch has a real possessive -s
//     ("Konings zwaard"), so "King's" -> "Konings" works in place.
// Gem names become material adjectives in -en (agaten, robijnen), the normal Dutch
// "made of X" pattern. Lower-case keys are mid-name variants: casing is preserved,
// and they are DERIVED from the capitalised entry so the two can never disagree.
