// (th4) Item affix SUFFIXES. The engine joins these with the NL_Ui row
// "%s of %s" -> "%s van %s", so each entry is the bare noun phrase after "van".
// The "the <noun>" family KEEPS ITS ARTICLE and picks it per Dutch gender --
// "van de Beer" but "van het Konijn". That is possible here, unlike in
// NL_AffixPrefix, because the noun lives inside the entry itself.
// Lower-case keys are mid-name variants and are DERIVED from the capitalised
// entry (article and noun both lowered) so the two can never drift.
