// (th4) NPC speech, keyed by the engine's own index. COMPLETE: 464 rows.
// The "|" terminator and the "\n \n" paragraph breaks are STRUCTURAL and are
// verified one-for-one against the English source, as is the leading space some
// lines carry. NOTE the English source stores "\n" as TWO CHARACTERS; the Dutch
// must carry the same number of REAL newlines. Comparing like-for-like is what let
// a literal-backslash-n bug through earlier, so the check now compares the English
// two-char count against the Dutch real-newline count.
// Recurring texts (the Na-Krul incantations repeat at 15 ids, each grimoire has a
// "first read" and a "re-read" variant, the dungeon plaques recur) are GENERATED
// from the identical English source in nl/sp_dup.py, so two copies cannot drift.
// KEPT VERBATIM, not translated: the Latin incantations that unseal Na-Krul, the
// demonic invocation at id 350, the .TRN filename at 270/276 and the developer
// note at 278.
// Voices are preserved rather than flattened: Cain formal and archaic, Farnham
// slurred with dropped consonants, Snotspill in broken pidgin, Adria oracular,
// Wirt mercenary, and Diablo's Dark Campaign briefings cold and imperious --
// addressing the player with the familiar "je/jij" the townsfolk never use.
static const IdxStr NL_Speech[] = {
	{ 0, " Ahh, het verhaal van onze Koning, is het niet?  De tragische val van Leoric was een harde slag voor dit land.  Het volk heeft de Koning altijd bemind, en nu leeft het in doodsangst voor hem.  De vraag die ik mezelf steeds stel is hoe hij zo ver van het Licht kon afdwalen, want Leoric was altijd de vroomste der mensen.  Alleen de laagste machten van de Hel konden een mens zo volkomen van binnenuit vernietigen... |" },
	{ 1, "Het dorp heeft uw hulp nodig, goede meester!  Enkele maanden geleden werd de zoon van Koning Leoric, Prins Albrecht, ontvoerd.  De Koning ontstak in woede en doorzocht het dorp naar zijn vermiste kind.  Met elke dag die verstreek leek Leoric dieper in waanzin weg te zinken.  Hij gaf onschuldige dorpelingen de schuld van de verdwijning van de jongen en liet hen wreed terechtstellen.  Minder dan de helft van ons overleefde zijn krankzinnigheid...\n \nDe Ridders en Priesters van de Koning trachtten hem te kalmeren, maar hij keerde zich tegen hen en helaas werden zij gedwongen hem te doden.  Met zijn laatste adem riep de Koning een verschrikkelijke vloek af over zijn voormalige volgelingen.  Hij zwoer dat zij hem eeuwig in duisternis zouden dienen...\n \nEn hier nemen de zaken een nog duisterder wending dan ik voor mogelijk hield!  Onze voormalige Koning is uit zijn eeuwige slaap herrezen en voert nu een legioen ondode dienaren aan in het Labyrint.  Zijn lichaam werd begraven in een tombe drie niveaus onder de Kathedraal.  Alstublieft, goede meester, breng zijn ziel tot rust door zijn nu vervloekte gedaante te vernietigen... |" },
	{ 2, "Zoals ik u zei, goede meester, de Koning werd drie niveaus lager bijgezet.  Hij is daarbeneden, wachtend in de rottende duisternis op zijn kans om dit land te vernietigen... |" },
	{ 3, "De vloek van onze Koning is voorbij, maar ik vrees dat het slechts een deel was van een groter kwaad dat aan het werk is.  Toch kunnen wij nog gered worden van de duisternis die ons land verteert, want uw overwinning is een goed voorteken.  Moge het Licht u op uw weg leiden, goede meester. |" },
	{ 4, "Het verlies van zijn zoon was te veel voor Koning Leoric.  Ik deed wat ik kon om zijn waanzin te verzachten, maar uiteindelijk overmande zij hem.  Een zwarte vloek hangt sinds die dag over dit koninkrijk, maar wellicht zou de vloek worden opgeheven als u zijn geest uit zijn aardse kerker zou bevrijden... |" },
	{ 5, "Ik denk niet graag na over hoe de Koning stierf.  Ik herinner hem me liever als de goede en rechtvaardige heerser die hij was.  Zijn dood was zo droevig en voelde op de een of andere manier heel verkeerd. |" },
	{ 6, "Ik maakte veel van de wapens en het meeste van het harnas waarmee Koning Leoric zijn ridders uitrustte.  Ik smeedde zelfs een enorm tweehandig zwaard van het fijnste mithril voor hem, met een bijpassende veldkroon.  Ik kan nog altijd niet geloven hoe hij stierf, maar het moet een duistere macht zijn geweest die hem krankzinnig maakte! |" },
	{ 7, "Kan me niks schelen.  Luister, geen skelet wordt MIJN koning.  Leoric is Koning.  Koning, hoor je me?  LEVE DE KONING! |" },
	{ 8, "De doden die onder de levenden wandelen volgen de vervloekte Koning.  Hij bezit de macht om nog meer krijgers op te wekken voor een steeds groeiend leger van ondoden.  Als u zijn heerschappij niet stopt, zal hij zeker door dit land trekken en allen doden die hier nog leven. |" },
	{ 9, "Kijk, ik drijf hier handel.  Ik verkoop geen inlichtingen, en ik geef niets om een of andere Koning die al langer dood is dan ik leef.  Als je iets nodig hebt om tegen die Koning der ondoden te gebruiken, dan kan ik je wel helpen... |" },
	{ 10, "De warmte van het leven is mijn tombe binnengekomen.  Bereid u voor, sterveling, om mijn Meester in eeuwigheid te dienen! |" },
	{ 11, "Ik zie dat dit vreemde gedrag ook u verbaast.  Ik zou vermoeden dat, aangezien veel demonen het licht van de zon vrezen en geloven dat het grote macht bezit, de rijzende zon op het bord waarover u spreekt hen heeft doen denken dat ook dat arcane krachten bezit.  Hmm, wellicht zijn zij niet allen zo slim als wij vreesden... |" },
	{ 12, "Meester, ik heb een vreemde ervaring te vertellen.  Ik weet dat u grote kennis bezit van die monsterlijkheden die het labyrint bewonen, en dit is iets wat ik met de beste wil ter wereld niet kan begrijpen...  Ik werd in de nacht gewekt door een schrapend geluid vlak buiten mijn herberg.  Toen ik uit mijn slaapkamer keek, zag ik de gedaanten van kleine demonachtige wezens op het erf.  Na korte tijd renden zij weg, maar niet voordat zij het uithangbord van mijn herberg hadden gestolen.  Ik begrijp niet waarom de demonen mijn bord zouden stelen maar mijn gezin met rust laten...  vreemd, nietwaar? |" },
	{ 13, "Och, u had mijn uithangbord niet hoeven terugbrengen, maar ik veronderstel dat het mij de kosten van een nieuw bord bespaart.  Wel, laat eens zien, wat zou ik u als beloning kunnen geven voor het vinden ervan?  Hmmm, wat hebben wij hier...  ah, ja!  Deze muts werd in een van de kamers achtergelaten door een magier die hier enige tijd geleden verbleef.  Wellicht is zij van enige waarde voor u. |" },
	{ 14, "Lieve hemel, demonen die 's nachts door het dorp rennen en onze huizen plunderen - is niets meer heilig?  Ik hoop dat Ogden en Garda ongedeerd zijn.  Ik neem aan dat zij naar mij toe zouden komen als zij gewond waren... |" },
	{ 15, "Och hemel!  Is het bord daar gebleven?  Mijn grootmoeder en ik moeten er dwars doorheen geslapen hebben.  Geloofd zij het Licht dat die monsters de herberg niet hebben aangevallen. |" },
	{ 16, "Demonen hebben Ogdens uithangbord gestolen, zegt u?  Dat klinkt niet erg als de gruweldaden waarvan ik heb gehoord - of die ik heb gezien. \n \nDemonen zijn erop uit uw hart eruit te rukken, niet uw uithangbord. |" },
	{ 17, "Weet je wat ik denk?  Iemand heeft dat bord gepakt, en die wil er veel geld voor.  Als ik Ogden was...  en dat ben ik niet, maar als ik het was...  dan kocht ik gewoon een nieuw bord met een mooie tekening erop.  Misschien een lekkere pul bier of een stuk kaas... |" },
	{ 18, "Geen sterveling kan de geest van een demon werkelijk doorgronden.  \n \nLaat hun grillige daden u nooit verwarren, want ook dat kan hun opzet zijn. |" },
	{ 19, "Wat - beweert hij dat ik dat gepakt heb?  Ik neem aan dat Griswold ook aan zijn kant staat. \n \nKijk, ik ben maanden geleden al gestopt met simpele borddiefstal.  Aan een stuk hout valt geen winst te maken. |" },
	{ 20, "H\xe9 - Jij die alles doodt!  Jij haalt Magisch Vaandel of wij vallen aan!  Jij niet weg met leven!  Jij doodt grote lelijkerds en geeft Magie terug.  Ga voorbij hoek en deur, vind lelijkerds.  Jij geeft, jij gaat! |" },
	{ 21, "Jij doodt lelijkerds, haalt vaandel.  Jij brengt naar mij, of anders... |" },
	{ 22, "Jij geeft!  Ja, goed!  Ga nu, wij sterk.  Wij doden alles met grote Magie! |" },
	{ 23, "Dit voorspelt weinig goeds, want het bevestigt mijn duisterste vrees.  Hoewel ik mezelf niet toestond de oude legenden te geloven, kan ik ze nu niet meer ontkennen.  Wellicht is de tijd gekomen om te onthullen wie ik ben.\n \nMijn ware naam is Deckard Cain de Oudste, en ik ben de laatste afstammeling van een oude Broederschap die zich wijdde aan het bewaken van de geheimen van een tijdloos kwaad.  Een kwaad dat nu overduidelijk is losgelaten.\n \nAartsbisschop Lazarus, ooit de meest vertrouwde raadsman van Koning Leoric, leidde een gezelschap eenvoudige dorpelingen het Labyrint in om de vermiste zoon van de Koning, Albrecht, te vinden.  Geruime tijd verstreek voordat zij terugkeerden, en slechts weinigen ontkwamen met het leven.\n \nVervloek mij als dwaas!  Ik had zijn verhulde verraad toen al moeten vermoeden.  Het moet Lazarus zelf zijn geweest die Albrecht ontvoerde en hem sindsdien binnen het Labyrint verborgen houdt.  Ik begrijp niet waarom de Aartsbisschop zich tot de duisternis wendde, of wat zijn belang bij het kind is, tenzij hij hem aan zijn duistere meesters wil offeren!\n \nDat moet zijn plan zijn!  De overlevenden van zijn 'reddingsgezelschap' zeggen dat Lazarus voor het laatst werd gezien terwijl hij de diepste ingewanden van het labyrint in rende.  U moet zich haasten en de prins redden van het offermes van deze waanzinnige duivel! |" },
	{ 24, "U moet zich haasten en Albrecht uit de handen van Lazarus redden.  De prins en het volk van dit koninkrijk rekenen op u! |" },
	{ 25, "Uw verhaal is bijzonder grimmig, mijn vriend.  Lazarus zal zeker in de Hel branden voor zijn afschuwelijke daad.  De jongen die u beschrijft is niet onze prins, maar ik geloof dat Albrecht nog steeds in gevaar kan zijn.  Het machtssymbool waarover u spreekt moet een portaal zijn in het hart zelf van het labyrint.\n \nWeet dit, mijn vriend - het kwaad waartegen u optrekt is de duistere Heer van Verschrikking.  Hij is bij stervelingen bekend als Diablo.  Hij was het die vele eeuwen geleden in het Labyrint werd opgesloten, en ik vrees dat hij opnieuw chaos wil zaaien in het rijk der mensen.  U moet door het portaal gaan en Diablo vernietigen voordat het te laat is! |" },
	{ 26, "Lazarus was de Aartsbisschop die veel van de dorpelingen het labyrint in leidde.  Ik verloor die dag veel goede vrienden, en Lazarus keerde nooit terug.  Ik neem aan dat hij samen met de meesten van de anderen is omgekomen.  Als u mij een gunst wilt bewijzen, goede meester - spreek alstublieft niet met Farnham over die dag. |" },
	{ 29, "Ik was geschokt toen ik hoorde wat de dorpelingen die nacht van plan waren.  Ik dacht dat Lazarus van alle mensen meer verstand zou hebben gehad.  Hij was een Aartsbisschop, en leek zich altijd zo om de dorpelingen van Tristram te bekommeren.  Zovelen raakten gewond, ik kon hen niet allen redden... |" },
	{ 30, "Ik herinner me Lazarus als een zeer vriendelijk en gulhartig man.  Hij sprak op de begrafenis van mijn moeder, en steunde mijn grootmoeder en mij in een zeer moeilijke tijd.  Ik bid elke avond dat hij op de een of andere manier nog leeft en veilig is. |" },
	{ 31, "Ik was erbij toen Lazarus ons het labyrint in leidde.  Hij sprak van heilige vergelding, maar toen wij die helgebroedsels begonnen te bevechten, hief hij zijn strijdknots niet eens tegen hen op.  Hij rende alleen maar dieper de schemerige, eindeloze kamers in die vol zaten met de dienaren der duisternis! |" },
	{ 32, "Ze steken, dan bijten ze, dan zijn ze overal om je heen.  Leugenaar!  LEUGENAAR!  Ze zijn allemaal dood!  Dood!  Hoor je me?  Ze blijven maar vallen en vallen...  hun bloed dat over de hele vloer stroomt...  allemaal zijn schuld... |" },
	{ 33, "Ik kende deze Lazarus van wie u spreekt niet, maar ik voel wel een groot conflict in zijn wezen.  Hij vormt een groot gevaar, en zal voor niets terugdeinzen om de machten der duisternis te dienen die hem als de hunne hebben opge\xebist. |" },
	{ 34, "Ja, de rechtschapen Lazarus, die z\xf3\xf3 doeltreffend was tegen die monsters daarbeneden.  Heeft mijn been er niet mee gered, wel?  Kijk, ik geef je een gratis advies.  Vraag het Farnham, hij was erbij. |" },
	{ 35, "Staak uw dwaze zoektocht.  Al wat u wacht is de gramschap van mijn Meester!  U bent te laat om het kind te redden.  Nu zult u zich bij hem voegen in de Hel! |" },
	{ 37, "Hmm, ik weet niet wat ik u hierover kan vertellen dat werkelijk van nut zal zijn.  Het water dat onze putten vult komt uit een ondergrondse bron.  Ik heb gehoord van een tunnel die naar een groot meer leidt - wellicht zijn zij een en hetzelfde.  Helaas weet ik niet wat onze watervoorziening zou kunnen bezoedelen. |" },
	{ 38, "Ik heb altijd getracht een grote voorraad levensmiddelen en drank in onze kelder te houden, maar nu de hele stad zonder vers water zit, zullen zelfs onze voorraden spoedig opdrogen. \n \nAlstublieft, doe wat u kunt, of ik weet niet wat wij moeten beginnen. |" },
	{ 39, "Ik ben blij dat ik u nog op tijd inhaalde!  Onze putten zijn brak en stilstaand geworden en enkele dorpelingen zijn ziek geworden van het drinken ervan.  Onze voorraden vers water raken snel op.  Ik geloof dat er een doorgang is die naar de bronnen leidt die onze stad voeden.  Zoek alstublieft uit wat deze ramp heeft veroorzaakt, of wij zullen allen zeker omkomen. |" },
	{ 40, "Alstublieft, u moet zich haasten.  Elk uur dat verstrijkt brengt ons dichter bij een leven zonder drinkwater. \n \nWij kunnen niet lang overleven zonder uw hulp. |" },
	{ 41, "Wat zegt u daar - de loutere aanwezigheid van de demonen heeft het water bezoedeld?  O, waarlijk schuilt er een groot kwaad onder onze stad, maar uw volharding en moed geven ons hoop.  Neem alstublieft deze ring - wellicht helpt hij u bij het vernietigen van zulke verdorven wezens. |" },
	{ 42, "Mijn grootmoeder is erg zwak, en Garda zegt dat we het water uit de putten niet mogen drinken.  Alstublieft, kunt u iets doen om ons te helpen? |" },
	{ 43, "Pepin heeft u de waarheid verteld.  Wij zullen dringend vers water nodig hebben, en snel.  Ik heb geprobeerd een van de kleinere putten schoon te maken, maar hij stinkt naar stilstaand vuil.  Hij moet bij de bron verstopt raken. |" },
	{ 44, "Drink jij water? |" },
	{ 45, "Het volk van Tristram zal sterven als u het verse water niet terugbrengt in hun putten. \n \nWeet dit - demonen liggen aan de kern van deze zaak, maar zij blijven onwetend van wat zij hebben voortgebracht. |" },
	{ 46, "Voor \xe9\xe9n keer sta ik aan jouw kant.  Mijn handel droogt op - bij wijze van spreken - als ik geen markt heb om aan te verkopen.  Zoek maar snel uit wat er aan de hand is! |" },
	{ 47, "Een boek dat spreekt van een kamer van menselijke beenderen?  Wel, een Kamer van Been wordt genoemd in bepaalde archa\xefsche geschriften die ik in de bibliotheken van het Oosten bestudeerde.  Deze folianten gaven te kennen dat de Heren van de onderwereld, wanneer zij grote schatten wilden beschermen, domeinen schiepen waarin zij die stierven bij een poging die schat te stelen voor eeuwig gebonden zouden zijn haar te verdedigen.  Een verwrongen, maar vreemd passend einde? |" },
	{ 48, "Ik vrees dat ik daar niets van weet, goede meester.  Cain heeft veel boeken die van enig nut kunnen zijn. |" },
	{ 49, "Dit klinkt als een zeer gevaarlijke plek.  Als u zich daarheen waagt, wees dan uiterst voorzichtig. |" },
	{ 50, "Ik vrees dat ik daar niets over heb gehoord.  Wellicht kan Cain de Verhalenverteller van enig nut zijn. |" },
	{ 51, "Ik weet niets van die plek, maar u kunt het Cain vragen.  Hij spreekt over vele dingen, en het zou mij niet verbazen als hij enige antwoorden op uw vraag had. |" },
	{ 52, "Ok\xe9, luister dus.  Er is een kamer van hout, zie je.  En zijn vrouw, je weet wel - zij - zegt tegen de boom...  want je moet wachten.  Dan zeg ik, dat zou tegen hem kunnen werken, maar als je denkt dat ik hiervoor ga BETALEN...  je...  eh...  ja. |" },
	{ 53, "U zult een eeuwige dienaar van de duistere heren worden indien u in dit vervloekte domein omkomt. \n \nBetreed de Kamer van Been op eigen risico. |" },
	{ 54, "Een uitgestrekte en mysterieuze schat, zeg je?  Misschien wil ik wel een paar dingen van je overnemen...  of beter nog, heb je geen zeldzame en dure voorraden nodig om deze beproeving door te komen? |" },
	{ 55, "Het schijnt dat Aartsbisschop Lazarus veel van de dorpsmannen ophitste om zich in het Labyrint te wagen om de vermiste zoon van de Koning te vinden.  Hij speelde in op hun angsten en zweepte hen op tot een razende menigte.  Geen van hen was voorbereid op wat in de koude aarde lag...  Lazarus liet hen daarbeneden achter - in de klauwen van onuitsprekelijke gruwelen - om te sterven. |" },
	{ 56, "Ja, Farnham heeft iets gemompeld over een logge bruut die een woest wapen hanteerde.  Ik geloof dat hij hem een slachter noemde. |" },
	{ 57, "Bij het Licht, ik ken deze verdorven demon.  Velen droegen de littekens van zijn gramschap op hun lichaam toen de weinige overlevenden van de stormloop onder leiding van Lazarus uit de Kathedraal kropen.  Ik weet niet waarmee hij zijn slachtoffers openreet, maar het kan niet van deze wereld zijn geweest.  Het liet wonden achter die etterden van ziekte en zelfs ik vond ze bijna onmogelijk te behandelen.  Wees op uw hoede als u van plan bent deze duivel te bevechten... |" },
	{ 58, "Toen Farnham iets zei over een slachter die mensen doodde, wuifde ik het meteen weg.  Maar nu u het ter sprake brengt, is het misschien waar. |" },
	{ 59, "Ik zag wat Farnham de Slachter noemt terwijl hij een pad door de lichamen van mijn vrienden maaide.  Hij zwaaide met een hakmes zo groot als een bijl, hakte ledematen af en velde dappere mannen waar zij stonden.  Ik raakte van het gevecht gescheiden door een zwerm kleine krijsende demonen en vond op de een of andere manier de trap naar buiten.  Ik heb dat afzichtelijke beest nooit teruggezien, maar zijn bloedbevlekte gelaat achtervolgt mij tot op de dag van vandaag. |" },
	{ 60, "Groot!  Groot hakmes dat al mijn vrienden doodt.  Kon hem niet stoppen, moest wegrennen, kon ze niet redden.  Opgesloten in een kamer met zoveel lichamen...  zoveel vrienden...  NEEEEEEEEE! |" },
	{ 61, "De Slachter is een sadistisch wezen dat genot schept in de foltering en pijn van anderen.  U hebt zijn handwerk gezien in de dronkaard Farnham.  Zijn vernietiging zal veel doen om de veiligheid van dit dorp te waarborgen. |" },
	{ 62, "Ik weet meer over die gruwelijke duivel dan je zou denken.  Zijn vriendjes kregen mij te pakken en wisten mijn been te grijpen voordat Griswold mij uit dat gat trok. \n \nIk zeg het maar botweg - dood hem voordat hij jou doodt en jouw lijk aan zijn verzameling toevoegt. |" },
	{ 63, "Alstublieft, luister naar mij.  Aartsbisschop Lazarus, hij leidde ons hierheen om de verloren prins te vinden.  De schoft leidde ons in een val!  Nu is iedereen dood...  gedood door een demon die hij de Slachter noemde.  Wreek ons!  Vind deze Slachter en versla hem zodat onze zielen eindelijk kunnen rusten... |" },
	{ 65, "U draagt een merkwaardig rijm voor, geschreven in een stijl die mij aan andere werken doet denken.  Laat mij nadenken - hoe ging het ook alweer?\n \n...Duisternis omhult de Verborgene.  Ogen die ongezien gloeien, met slechts het geluid van scheermesklauwen die kort schrapen om die arme zielen te kwellen die voor alle eeuwigheid blind zijn gemaakt.  De kerker voor hen die zo verdoemd zijn heet de Hallen der Blinden... |" },
	{ 66, "Ik heb nooit veel om po\xebzie gegeven.  Zo nu en dan had ik reden om minstrelen in te huren toen de herberg goed liep, maar dat lijkt nu zo lang geleden. \n \nWat?  O, ja...  eh, wel, ik veronderstel dat u kunt kijken wat iemand anders weet. |" },
	{ 67, "Dit komt mij op de een of andere manier bekend voor.  Ik meen mij te herinneren dat ik iets als dat gedicht las tijdens onderzoek naar de geschiedenis van demonische kwalen.  Het sprak van een plaats van groot kwaad die...  wacht - u gaat daar toch niet heen? |" },
	{ 68, "Als u vragen hebt over blindheid, moet u met Pepin praten.  Ik weet dat hij mijn grootmoeder een drank gaf die haar zicht hielp opklaren, dus misschien kan hij u ook helpen. |" },
	{ 69, "Ik vrees dat ik noch gehoord noch gezien heb van een plaats die aan uw levendige beschrijving voldoet, mijn vriend.  Wellicht kan Cain de Verhalenverteller van enig nut zijn. |" },
	{ 70, "Kijk hier eens...  dat is best grappig, h\xe8?  Snap je?  Blind - kijk hier? |" },
	{ 71, "Dit is een plaats van grote kwelling en verschrikking, en dient daarmee haar meester goed. \n \nTreed behoedzaam, of u zou er zelf veel langer kunnen blijven dan u had verwacht. |" },
	{ 72, "Even kijken, verkoop ik je iets?  Nee.  Geef je mij geld om je hierover te vertellen?  Nee.  Vertrek je nu om te gaan praten met de verhalenverteller die voor dit soort dingen leeft?  Ja. |" },
	{ 73, "U beweert met Lachdanan te hebben gesproken?  Hij was een groot held tijdens zijn leven.  Lachdanan was een eervol en rechtvaardig man die zijn Koning jarenlang trouw diende.  Maar dat weet u natuurlijk al.\n \nVan hen die in de greep van de Vloek van de Koning raakten, zou Lachdanan het minst geneigd zijn zich zonder strijd aan de duisternis over te geven, dus ik veronderstel dat uw verhaal waar kan zijn.  Als ik in uw plaats was, mijn vriend, zou ik een manier vinden om hem uit zijn foltering te verlossen. |" },
	{ 74, "U spreekt over een dappere krijger die al lang dood is!  Ik duld geen gepraat over het spreken met heengegane zielen op mijn herbergserf, dank u zeer. |" },
	{ 75, "Een gouden elixer, zegt u.  Ik heb nog nooit een drank van die kleur bereid, dus ik kan u niet zeggen wat het met u zou doen als u het zou proberen te drinken.  Als uw heler raad ik u ten sterkste aan: mocht u zo'n elixer vinden, doe dan wat Lachdanan vraagt en probeer het NIET te gebruiken. |" },
	{ 76, "Ik heb nog nooit van een Lachdanan gehoord.  Het spijt me, maar ik denk niet dat ik u erg van dienst kan zijn. |" },
	{ 77, "Als het werkelijk Lachdanan is die u hebt ontmoet, dan zou ik u aanraden hem te helpen.  Ik heb bij verschillende gelegenheden met hem te maken gehad en vond hem eerlijk en trouw van aard.  De vloek die op de volgelingen van Koning Leoric viel, zou hem bijzonder zwaar treffen. |" },
	{ 78, " Lachdanan is dood.  Iedereen weet dat, en je maakt mij niets anders wijs.  Je kunt niet met de doden praten.  Ik weet het! |" },
	{ 79, "U kunt mensen ontmoeten die binnen het Labyrint gevangen zitten, zoals Lachdanan. \n \nIk bespeur in hem eer en grote schuld.  Help hem, en u helpt heel Tristram. |" },
	{ 80, "Wacht, laat me raden.  Cain werd verzwolgen door een gigantische spleet die onder hem openging.  Hij werd verast in een bal helvuur, en kan je vragen niet meer beantwoorden.  O, is dat niet wat er gebeurd is?  Dan neem ik aan dat je iets gaat kopen of je gaat je weg. |" },
	{ 81, "Alstublieft, dood mij niet, hoor mij slechts aan.  Ik was ooit Kapitein van de Ridders van Koning Leoric, en handhaafde de wetten van dit land met rechtvaardigheid en eer.  Toen viel zijn duistere Vloek op ons voor de rol die wij speelden in zijn tragische dood.  Terwijl mijn mederidders bezweken voor hun verwrongen lot, vluchtte ik uit de grafkamer van de Koning, zoekend naar een manier om mijzelf van de Vloek te bevrijden.  Ik faalde...\n \nIk heb gehoord van een Gouden Elixer dat de Vloek zou kunnen opheffen en mijn ziel rust zou geven, maar ik heb het niet kunnen vinden.  Mijn krachten nemen nu af, en daarmee ook het laatste van mijn menselijkheid.  Help mij alstublieft en vind het Elixer.  Ik zal uw moeite vergelden - dat zweer ik op mijn eer. |" },
	{ 82, "U hebt het Gouden Elixer niet gevonden.  Ik vrees dat ik voor eeuwig verdoemd ben.  Alstublieft, blijf het proberen... |" },
	{ 83, "U hebt mijn ziel van de verdoemenis gered, en daarvoor sta ik bij u in het krijt.  Als er ooit een manier is waarop ik u van gene zijde van het graf kan vergelden, zal ik die vinden, maar neem voor nu mijn helm.  Op de reis die ik ga ondernemen zal ik er weinig aan hebben.  Moge hij u beschermen tegen de duistere machten daarbeneden.  Ga met het Licht, mijn vriend... |" },
	{ 84, "Griswold spreekt van het Aambeeld van Woede - een legendarisch voorwerp waar lang naar gezocht is, maar dat nooit gevonden werd.  Gesmeed uit de metalen beenderen van de Scheermeskuildemonen, werd het Aambeeld van Woede gesmolten rond de schedels van de vijf machtigste magi\xebrs van de onderwereld.  Bekerfd met runen van macht en chaos, zal elk wapen of harnas dat op dit Aambeeld gesmeed wordt in het rijk van Chaos worden ondergedompeld en met magische eigenschappen worden doordrongen.  Men zegt dat de onvoorspelbare aard van Chaos het moeilijk maakt te weten wat de uitkomst van dit smeedwerk zal zijn... |" },
	{ 85, "Denkt u niet dat Griswold een betere persoon is om dit aan te vragen?  Hij is nogal handig, weet u. |" },
	{ 86, "Als u informatie had gezocht over de Vijzel der Genezing of de Zilveren Kelk der Zuivering, had ik u kunnen bijstaan, mijn vriend.  In deze zaak zou u echter beter af zijn met Griswold of Cain. |" },
	{ 87, "Griswolds vader vertelde sommigen van ons toen wij opgroeiden over een reusachtig aambeeld waarmee machtige wapens werden gemaakt.  Hij zei dat wanneer een hamer op dit aambeeld sloeg, de grond met grote woede schudde.  Telkens als de aarde beweegt, denk ik aan dat verhaal. |" },
	{ 88, "Gegroet!  Het is altijd een genoegen een van mijn beste klanten te zien!  Ik weet dat u zich steeds dieper in het Labyrint hebt gewaagd, en er is een verhaal dat mij verteld is en dat u de moeite van het aanhoren waard kunt vinden...\n \nEen van de mannen die uit het Labyrint terugkeerde vertelde mij over een mystiek aambeeld dat hij tijdens zijn ontsnapping tegenkwam.  Zijn beschrijving deed mij denken aan legenden die ik in mijn jeugd hoorde over de brandende Helsmidse waar machtige magische wapens worden vervaardigd.  De legende wilde dat diep in de Helsmidse het Aambeeld van Woede rustte!  Dit Aambeeld bevatte de essentie zelf van de demonische onderwereld...\n \nMen zegt dat elk wapen dat op het brandende Aambeeld gesmeed wordt met grote macht wordt doordrongen.  Als dit aambeeld werkelijk het Aambeeld van Woede is, kan ik u wellicht een wapen maken dat zelfs de duisterste heer van de Hel kan verslaan! \n \nVind het Aambeeld voor mij, en ik ga aan het werk! |" },
	{ 89, "Nog niets, h\xe8?  Wel, blijf zoeken.  Een wapen dat op het Aambeeld gesmeed is zou uw beste hoop kunnen zijn, en ik weet zeker dat ik er een van legendarische afmetingen voor u kan maken. |" },
	{ 90, "Ik kan het nauwelijks geloven!  Dit is het Aambeeld van Woede - goed werk, mijn vriend.  Nu zullen wij die schoften laten zien dat er in de Hel geen dodelijker wapens zijn dan die door mensen gemaakt zijn!  Neem dit aan en moge het Licht u beschermen. |" },
	{ 91, "Griswold kan zijn aambeeld niet verkopen.  Wat moet hij dan?  En ik zou ook boos zijn als iemand mijn aambeeld pakte! |" },
	{ 92, "Er zijn vele voorwerpen binnen het Labyrint die machten bezitten die het begrip van stervelingen te boven gaan.  Sommige daarvan bezitten fantastische macht die door het Licht of door de Duisternis gebruikt kan worden.  Het Aambeeld van beneden veiligstellen zou de loop van de Zondeoorlog naar het Licht kunnen doen kantelen. |" },
	{ 93, "Als jij dat voorwerp voor Griswold zou vinden, zou dat mijn zaken hier flink kunnen drukken.  Ach, je vindt het toch nooit. |" },
	{ 94, "De Poort van Bloed en de Zaal van Vuur zijn ori\xebntatiepunten van mystieke oorsprong.  Waar dit boek waaruit u las zich ook bevindt, het is zeker een plaats van grote macht.\n \nLegenden spreken van een voetstuk dat uit obsidiaan gehouwen is en waarop een poel van kokend bloed rust op een met beenderen bezet oppervlak.  Er zijn ook toespelingen op Stenen van Bloed die een deur openen die een oude schat bewaakt...\n \nDe aard van deze schat is in speculatie gehuld, mijn vriend, maar men zegt dat de oude held Arkaine het heilige harnas Moed in een geheim gewelf plaatste.  Arkaine was de eerste sterveling die het tij van de Zondeoorlog keerde en de legioenen der duisternis terugdreef naar de Brandende Hellen.\n \nVlak voordat Arkaine stierf, werd zijn harnas in een geheim gewelf verborgen.  Men zegt dat wanneer dit heilige harnas opnieuw nodig is, er een held zal opstaan om Moed weer te dragen.  Wellicht bent u die held... |" },
	{ 95, "Elk kind hoort het verhaal van de krijger Arkaine en zijn mystieke harnas dat Moed heet.  Als u zijn rustplaats zou kunnen vinden, zou u goed beschermd zijn tegen het kwaad in het Labyrint. |" },
	{ 96, "Hmm...  het klinkt als iets wat ik zou moeten weten, maar ik ben zo druk geweest met het leren van nieuwe geneeswijzen en het maken van betere elixers dat ik het vergeten moet zijn.  Sorry... |" },
	{ 97, "Het verhaal van het magische harnas dat Moed heet is iets waar ik de jongens vaak over hoorde praten.  U kunt het beter aan een van de mannen in het dorp vragen. |" },
	{ 98, "Het harnas dat Moed heet zou de doorslag in uw voordeel kunnen geven.  Ik zal u zeggen dat velen ernaar hebben gezocht - ikzelf inbegrepen.  Arkaine heeft het goed verborgen, mijn vriend, en er is meer dan een beetje geluk nodig om de geheimen te ontsluiten die het al die vele jaren verborgen hebben gehouden. |" },
	{ 99, "Zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz... |" },
	{ 100, "Mocht u deze Stenen van Bloed vinden, gebruik ze dan behoedzaam. \n \nDe weg is vol gevaar en uw enige hoop rust in het vertrouwen in uzelf. |" },
	{ 101, "Ben je van plan het harnas dat Moed heet te vinden? \n \nNiemand heeft ooit uitgevist waar Arkaine dat spul verstopte, en als mijn contacten het niet konden vinden, betwijfel ik ten zeerste of jij het ooit zult vinden. |" },
	{ 102, "Ik ken slechts \xe9\xe9n legende die spreekt van een krijger zoals u beschrijft.  Zijn verhaal is te vinden in de oude kronieken van de Zondeoorlog...\n \nBevlekt door duizend jaar oorlog, bloed en dood staat de Krijgsheer van Bloed op een berg van zijn verscheurde slachtoffers.  Zijn duistere kling schreeuwt een zwarte vloek naar de levenden; een gefolterde uitnodiging aan ieder die voor deze Beul van de Hel zou willen staan.\n \nEr staat ook geschreven dat hoewel hij ooit een sterveling was die tijdens de Zondeoorlog naast het Legioen der Duisternis vocht, hij zijn menselijkheid verloor aan zijn onverzadigbare honger naar bloed. |" },
	{ 103, "Ik vrees dat ik niets heb gehoord over zo'n wrede krijger, goede meester.  Ik hoop dat u hem niet hoeft te bevechten, want hij klinkt uiterst gevaarlijk. |" },
	{ 104, "Cain zou u veel meer over zoiets kunnen vertellen dan ik ooit zou willen weten. |" },
	{ 105, "Als u zo'n felle tegenstander moet bevechten, moge het Licht dan uw gids en uw verdediger zijn.  Ik zal aan u denken. |" },
	{ 106, "Duistere en boosaardige legenden omringen de Krijgsheer van Bloed.  Wees goed voorbereid, mijn vriend, want hij toont geen genade en geeft geen pardon. |" },
	{ 107, "Moet je het altijd over Bloed hebben?  Wat dacht je van bloemen, en zonneschijn, en dat mooie meisje dat de drankjes brengt.  Luister eens, vriend - je bent obsessief, weet je dat? |" },
	{ 108, "Zijn bedrevenheid met de kling is ontzagwekkend, en hij heeft duizenden jaren geleefd en niets dan oorlog gekend.  Het spijt mij...  ik kan niet zien of u hem zult verslaan. |" },
	{ 109, "Ik heb nooit zaken gedaan met die Krijgsheer waar je het over hebt, maar het klinkt alsof hij heel wat zwaarden verslijt.  Zou het niet erg vinden zijn legers te bevoorraden... |" },
	{ 110, "Mijn kling zingt om uw bloed, sterveling, en bij mijn duistere meesters zal het haar niet worden ontzegd. |" },
	{ 111, "Griswold spreekt van de Hemelsteen die bestemd was voor de enclave in het oosten.  Hij werd daarheen gebracht voor nadere studie.  Deze steen gloeide met een energie die op de een of andere manier een zicht schonk dat een normaal mens niet kan bezitten.  Ik weet niet welke geheimen hij bevat, mijn vriend, maar het vinden van deze steen zou zeker zeer waardevol blijken. |" },
	{ 112, "De karavaan stopte hier om voorraden in te slaan voor hun reis naar het oosten.  Ik verkocht hun een heel assortiment vers fruit en enkele voortreffelijke zoete broden die Garda net had gebakken.  Jammer wat er met hen is gebeurd... |" },
	{ 113, "Ik weet niet wat zij dachten te kunnen zien met die steen, maar dit zeg ik wel.  Als er stenen uit de hemel vallen, kun je maar beter voorzichtig zijn! |" },
	{ 114, "Wel, een karavaan met enkele zeer belangrijke lieden stopte hier inderdaad, maar dat is alweer een hele tijd geleden.  Zij hadden vreemde accenten en begonnen aan een lange reis, meen ik mij te herinneren. \n \nIk zie niet in hoe u zou kunnen hopen iets terug te vinden dat zij bij zich droegen. |" },
	{ 115, "Blijf even - ik heb een verhaal dat u interessant kunt vinden.  Een karavaan op weg naar de oostelijke koninkrijken trok hier enige tijd geleden doorheen.  Zij zou een stuk van de hemel vervoeren dat op aarde was gevallen!  De karavaan werd even ten noorden van hier langs de weg overvallen door gemantelde ruiters.  Ik doorzocht het wrak naar deze hemelsteen, maar hij was nergens te vinden.  Mocht u hem vinden, dan geloof ik dat ik er iets nuttigs van kan maken. |" },
	{ 116, "Ik wacht nog steeds tot u mij die steen uit de hemel brengt.  Ik weet dat ik er iets krachtigs van kan maken. |" },
	{ 117, "Laat eens zien - ja...  ja, het is zoals ik dacht.  Geef mij een ogenblik...\n \nAh, hier bent u.  Ik heb stukken van de steen in een zilveren ring gezet die mijn vader mij naliet.  Ik hoop dat hij u goed van dienst is. |" },
	{ 118, "Ik had vroeger een mooie ring; een echt dure, met blauw en groen en rood en zilver.  Weet niet meer wat ermee gebeurd is, trouwens.  Ik mis die ring echt... |" },
	{ 119, "De Hemelsteen is zeer krachtig, en ware het iemand anders dan Griswold die u vroeg hem te vinden, ik zou het verhinderen.  Hij zal zijn krachten aanwenden en het gebruik ervan zal ons allen ten goede komen. |" },
	{ 120, "Als iemand iets van die steen kan maken, dan Griswold.  Hij weet wat hij doet, en hoezeer ik ook probeer zijn klanten af te snoepen, ik heb respect voor de kwaliteit van zijn werk. |" },
	{ 121, "De heks Adria zoekt een zwarte paddenstoel?  Ik weet evenveel van Zwarte Paddenstoelen als van Rode Haringen.  Wellicht kan Pepin de Heler u meer vertellen, maar dit is iets wat in geen van mijn verhalen of boeken te vinden is. |" },
	{ 122, "Laat ik dit zeggen.  Garda en ik zouden NOOIT, maar dan ook NOOIT zwarte paddenstoelen aan onze ge\xeb""erde gasten opdienen.  Als Adria paddenstoelen in haar stoofpot wil, dan is dat haar zaak, maar ik kan u niet helpen ze te vinden.  Zwarte paddenstoelen...  walgelijk! |" },
	{ 123, "De heks vertelde mij dat u op zoek was naar het brein van een demon om mij te helpen bij het maken van mijn elixer.  Het zou van grote waarde moeten zijn voor de velen die door die vuile beesten verwond raken, als ik de geheimen kan ontsluiten die de alchemie ervan naar mijn vermoeden bevat.  Als u het brein van een demon kunt verwijderen wanneer u hem doodt, zou ik u dankbaar zijn als u het mij zou brengen. |" },
	{ 124, "Uitstekend, dit is precies wat ik voor ogen had.  Ik kon het elixer zonder dit afmaken, maar het kan geen kwaad dit te bestuderen.  Zou u dit alstublieft naar de heks willen brengen?  Ik geloof dat zij het verwacht. |" },
	{ 125, "Ik denk dat Ogden misschien paddenstoelen in de voorraadkelder heeft.  Waarom vraagt u het hem niet? |" },
	{ 126, "Als Adria er geen heeft, kun je erop rekenen dat het werkelijk iets zeldzaams is.  Meer hulp kan ik je niet bieden, maar het klinkt als...  een enorme, kolossale, gezwollen, opgeblazen paddenstoel!  Wel, veel jachtplezier, neem ik aan. |" },
	{ 127, "Ogden mengt een MOORDDADIGE zwarte paddenstoel, maar ik word ziek als ik dat drink.  Luister, luister...  hier is het geheim - matiging is de sleutel! |" },
	{ 128, "Wat hebben wij hier?  Interessant, het lijkt een boek met reagentia.  Houd je ogen open voor een zwarte paddenstoel.  Hij zou vrij groot en gemakkelijk te herkennen moeten zijn.  Als je hem vindt, breng hem dan naar mij, wil je? |" },
	{ 129, "Het is een grote, zwarte paddenstoel die ik nodig heb.  Ga hem nu voor mij halen zodat ik hem kan gebruiken voor een bijzonder brouwsel waaraan ik werk. |" },
	{ 130, "Ja, dit zal volmaakt zijn voor een brouwsel dat ik maak.  Overigens zoekt de heler het brein van de een of andere demon zodat hij hen kan behandelen die door hun giftige venijn getroffen zijn.  Ik geloof dat hij er een elixer van wil maken.  Als je hem helpt te vinden wat hij nodig heeft, kijk dan of je een monster van het elixer voor mij kunt krijgen. |" },
	{ 131, "Waarom heb je dat hierheen gebracht?  Ik heb op dit moment geen demonenbrein nodig.  Ik heb wel wat van het elixer nodig waaraan de Heler werkt.  Hij heeft dat groteske orgaan nodig dat je vasthoudt, en breng mij dan het elixer.  Eenvoudig als je erover nadenkt, nietwaar? |" },
	{ 132, "Wat?  Breng je mij nu dat elixer van de heler?  Ik kon mijn brouwsel zonder afmaken.  Houd het zelf maar... |" },
	{ 133, "Ik heb geen paddenstoelen van welke maat of kleur dan ook te koop.  Wat dacht je van iets nuttigers? |" },
	{ 134, "hing" },
	{ 135, "Onze tijd raakt op!  Ik voel zijn duistere macht aanzwellen en alleen u kunt hem beletten zijn volle kracht te bereiken. |" },
	{ 136, "Ik weet zeker dat u uw uiterste best hebt gedaan, maar ik vrees dat zelfs uw kracht en wil niet genoeg zullen zijn.  Diablo staat nu op het hoogtepunt van zijn aardse macht, en u zult al uw moed en kracht nodig hebben om hem te verslaan.  Moge het Licht u beschermen en leiden, mijn vriend.  Ik zal helpen op elke wijze die ik kan. |" },
	{ 137, "Als de heks u niet kan helpen en voorstelt dat u Cain opzoekt, waarom denkt u dan dat ik iets zou weten?  Het klinkt alsof dit een zeer ernstige zaak is.  U kunt zich beter haasten en de verhalenverteller opzoeken zoals Adria voorstelt. |" },
	{ 138, "Ik kan weinig maken van het schrift op deze kaart, maar wellicht kunnen Adria of Cain u helpen ontcijferen waar het naar verwijst. \n \nIk kan zien dat het een kaart is van de sterren aan onze hemel, maar meer dan dat gaat mijn kunde te boven. |" },
	{ 139, "De beste persoon om zoiets aan te vragen zou onze verhalenverteller zijn. \n \nCain heeft veel kennis van oude geschriften, en dit is met gemak het oudst ogende stuk papier dat ik ooit heb gezien. |" },
	{ 140, "Ik heb nog nooit zo'n kaart gezien.  Waar hebt u die vandaan?  Hoewel ik geen idee heb hoe ik dit moet lezen, kunnen Cain of Adria wellicht de antwoorden geven die u zoekt. |" },
	{ 141, "Luister eens, kom dichterbij.  Ik weet niet of jij weet wat ik weet, maar je hebt hier echt iets te pakken.  Dat is een kaart. |" },
	{ 142, "O, ik vrees dat dit helemaal niets goeds voorspelt.  Deze sterrenkaart voorspelt een grote ramp, maar haar geheimen zijn niet aan mij om te vertellen.  De tijd is gekomen dat u een zeer ernstig gesprek met de Verhalenverteller voert... |" },
	{ 143, "Ik ben op zoek geweest naar een kaart, maar dat is het beslist niet.  Je moet dat aan Adria laten zien - zij kan je waarschijnlijk vertellen wat het is.  E\xe9n ding zal ik zeggen: het ziet er oud uit, en oud betekent meestal waardevol. |" },
	{ 144, "Alsjeblieeeft, geen pijn.  Niet doden.  Houd leven en volgende keer goed brengen aan jou. |" },
	{ 145, "Iets voor jou ben ik maken.  Nogmaals, niet doden Gharbad.  Leven en goed geven. \n \nJij neemt dit als bewijs ik houd woord... |" },
	{ 146, "Nog niets!  Bijna klaar. \n \nZeer machtig, zeer sterk.  Leven!  Leven! \n \nGeen pijn en belofte ik houd! |" },
	{ 147, "Dit te goed voor jou.  Zeer Machtig!  Jij wilt - jij neemt! |" },
	{ 148, "Wat?!  Waarom ben je hier?  Al deze onderbrekingen zijn genoeg om iemand krankzinnig te maken.  Hier, neem dit en laat mij aan mijn werk.  Val mij niet langer lastig! |" },
	{ 149, "Aaargh!  Uw nieuwsgierigheid zal uw dood zijn!!! |" },
	{ 150, "Hallo, mijn vriend.  Blijf even en luister... |" },
	{ 151, "Terwijl u zich dieper in het Labyrint waagt, kunt u daar folianten van grote kennis verborgen vinden. \n \nLees ze aandachtig, want zij kunnen u dingen vertellen die zelfs ik niet kan. |" },
	{ 152, "Ik ken vele mythen en legenden die antwoorden kunnen bevatten op vragen die kunnen rijzen tijdens uw tochten in het Labyrint.  Als u op uitdagingen en vragen stuit waarvan u de kennis zoekt, zoek mij dan op en ik zal u vertellen wat ik kan. |" },
	{ 153, "Griswold - een man van grote daden en grote moed.  Ik wed dat hij u nooit heeft verteld over de keer dat hij het Labyrint in ging om Wirt te redden, h\xe8?  Hij kent zijn deel van de gevaren die daar te vinden zijn, maar dat geldt inmiddels ook voor u.  Hij is een bekwaam vakman, en als hij beweert u op enige wijze te kunnen helpen, kunt u op zijn eerlijkheid en zijn vakmanschap rekenen. |" },
	{ 154, "Ogden bezit en drijft de herberg De Rijzende Zon nu bijna vier jaar.  Hij kocht haar slechts enkele korte maanden voordat hier alles naar de hel ging.  Hij en zijn vrouw Garda hebben het geld niet om te vertrekken, want zij investeerden alles wat zij hadden in een bestaan hier.  Hij is een goed man met een diep verantwoordelijkheidsbesef. |" },
	{ 155, "Arme Farnham.  Hij is een verontrustende herinnering aan het gedoemde gezelschap dat op die duistere dag met Lazarus de Kathedraal binnenging.  Hij ontkwam met het leven, maar zijn moed en een groot deel van zijn verstand bleven in een of andere duistere kuil achter.  Tegenwoordig vindt hij enkel troost op de bodem van zijn pul, maar in zijn voortdurende gebazel liggen soms brokjes waarheid begraven. |" },
	{ 156, "De heks, Adria, is een vreemde eend in de bijt hier in Tristram.  Zij kwam kort nadat de Kathedraal werd ontheiligd, terwijl vrijwel iedereen juist vluchtte.  Zij liet aan de rand van het dorp een kleine hut bouwen, schijnbaar in \xe9\xe9n nacht, en heeft toegang tot vele vreemde en arcane voorwerpen en kennisfolianten die zelfs ik nooit eerder heb gezien. |" },
	{ 157, "Het verhaal van Wirt is een beangstigend en tragisch verhaal.  Hij werd uit de armen van zijn moeder gerukt en het labyrint in gesleept door de kleine, vuile demonen die boosaardige speren hanteren.  Er werden die dag vele andere kinderen meegenomen, waaronder de zoon van Koning Leoric.  De Ridders van het paleis daalden af, maar keerden nooit terug.  De Smid vond de jongen, maar pas nadat de vuile beesten hem hadden gefolterd voor hun sadistische genoegens. |" },
	{ 158, "Ah, Pepin.  Ik reken hem tot een ware vriend - wellicht de naaste die ik hier heb.  Hij is soms wat warhoofdig, maar er heeft nooit een zorgzamer of attenter ziel bestaan.  Zijn kennis en vaardigheden worden door weinigen ge\xebvenaard, en zijn deur staat altijd open. |" },
	{ 159, "Gillian is een fijne vrouw.  Zeer geliefd om haar opgewektheid en haar snelle lach, neemt zij een bijzondere plaats in mijn hart in.  Zij blijft in de herberg om haar bejaarde grootmoeder te onderhouden, die te ziek is om te reizen.  Soms vrees ik voor haar veiligheid, maar ik weet dat elke man in het dorp liever zou sterven dan haar kwaad te zien geschieden. |" },
	{ 160, "Gegroet, goede meester.  Welkom in de Herberg De Rijzende Zon! |" },
	{ 161, "Vele avonturiers hebben de tafels van mijn herberg gesierd, en tienmaal zoveel verhalen zijn er verteld bij evenveel bier.  Het enige waarover ik hen ooit allen eens hoorde zijn, was dit oude spreekwoord.  Wellicht helpt het u.  Je kunt het vlees snijden, maar het bot moet je verbrijzelen. |" },
	{ 162, "Griswold de smid heeft buitengewoon veel verstand van wapens en harnassen.  Als u ooit werk aan uw uitrusting nodig hebt, is hij beslist de man om te zien. |" },
	{ 163, "Farnham brengt hier veel te veel tijd door en verdrinkt zijn verdriet in goedkoop bier.  Ik zou hem wegsturen, maar hij heeft zo geleden tijdens zijn tijd in het Labyrint. |" },
	{ 164, "Adria is wijs voor haar jaren, maar ik moet toegeven - zij maakt mij een beetje bang. \n \nWel, het doet er niet toe.  Als u ooit in voorwerpen van tovenarij moet handelen, houdt zij een vreemd goedgevulde hut aan net over de rivier. |" },
	{ 165, "Als u meer wilt weten over de geschiedenis van ons dorp, dan weet de verhalenverteller Cain heel wat over het verleden. |" },
	{ 166, "Wirt is een deugniet en een kleine schavuit.  Hij haalde altijd streken uit, en het is geen verrassing wat er met hem gebeurd is. \n \nHij zat waarschijnlijk ergens rond te scharrelen waar hij niet had moeten zijn.  Ik heb medelijden met de jongen, maar ik duld het gezelschap niet waarin hij verkeert.  |" },
	{ 167, "Pepin is een goed man - en beslist de vrijgevigste in het dorp.  Hij zorgt altijd voor de noden van anderen, maar het een of andere ongeluk lijkt hem overal te volgen... |" },
	{ 168, "Gillian, mijn schenkster?  Ware het niet om haar plichtsbesef jegens haar grootmoeder, dan was zij hier allang weggevlucht. \n \nDe hemel weet dat ik haar heb gesmeekt te vertrekken en haar zei dat ik op de oude vrouw zou passen, maar zij is te lief en te zorgzaam om dat te doen. |" },
	{ 169, "Wat scheelt u, mijn vriend? |" },
	{ 170, "Ik heb een zeer interessante ontdekking gedaan.  Anders dan wij kunnen de wezens in het Labyrint zichzelf genezen zonder hulp van dranken of magie.  Als u een van de monsters verwondt, zorg dan dat het dood is, anders kan het zich heel goed weer herstellen. |" },
	{ 171, "Voordat zij werd overgenomen door, wel, wat er ook beneden loert, was de Kathedraal een plaats van grote geleerdheid.  Er zijn daar vele boeken te vinden.  Als u er enige vindt, lees ze dan allemaal, want sommige kunnen geheimen bevatten over de werking van het Labyrint. |" },
	{ 172, "Griswold weet evenveel van de krijgskunst als ik van de geneeskunst.  Hij is een scherpzinnig koopman, maar zijn werk is onovertroffen.  O, ik veronderstel dat dat komt omdat hij de enige smid is die hier nog over is. |" },
	{ 173, "Cain is een ware vriend en een wijze geleerde.  Hij houdt een uitgestrekte bibliotheek bij en heeft een aangeboren vermogen de ware aard van vele dingen te doorgronden.  Als u ooit vragen hebt, is hij de persoon om naartoe te gaan. |" },
	{ 174, "Zelfs mijn vaardigheden hebben Farnham niet volledig kunnen genezen.  O, ik heb zijn lichaam kunnen herstellen, maar zijn geest en gemoed gaan alles te boven wat ik kan doen. |" },
	{ 175, "Hoewel ik enkele beperkte vormen van magie gebruik om de dranken en elixers te maken die ik hier bewaar, is Adria een ware tovenares.  Zij lijkt nooit te slapen, en zij heeft altijd toegang tot vele mystieke folianten en voorwerpen.  Ik geloof dat haar hut veel meer kan zijn dan het krot dat zij lijkt, maar ik krijg nooit voet binnen. |" },
	{ 176, "Arme Wirt.  Ik deed alles wat mogelijk was voor het kind, maar ik weet dat hij die houten stelt veracht die ik aan zijn been moest bevestigen.  Zijn wonden waren afzichtelijk.  Niemand - en zeker niet zo'n jong kind - zou moeten lijden zoals hij deed. |" },
	{ 177, "Ik begrijp werkelijk niet waarom Ogden hier in Tristram blijft.  Hij lijdt aan een lichte zenuwaandoening, maar hij is een intelligent en nijver man die het overal goed zou doen.  Ik veronderstel dat het de angst is voor de vele moorden die in het omringende land plaatsvinden, of wellicht de wensen van zijn vrouw die hem en zijn gezin houden waar zij zijn. |" },
	{ 178, "Ogdens schenkster is een lief meisje.  Haar grootmoeder is nogal ziek en lijdt aan waanvoorstellingen. \n \nZij beweert dat het visioenen zijn, maar daar heb ik hoe dan ook geen bewijs van. |" },
	{ 179, "Goedendag!  Waarmee kan ik u van dienst zijn? |" },
	{ 180, "Mijn grootmoeder droomde dat u zou komen en met mij zou praten.  Zij heeft visioenen, weet u, en kan in de toekomst kijken. |" },
	{ 181, "De vrouw aan de rand van het dorp is een heks!  Zij lijkt aardig genoeg, en haar naam, Adria, klinkt zeer aangenaam, maar ik ben erg bang voor haar. \n \nEr is iemand voor nodig die behoorlijk dapper is, zoals u, om te zien wat zij daar uitspookt. |" },
	{ 182, "Onze Smid is een bron van trots voor het volk van Tristram.  Hij is niet alleen een meestervakman die vele wedstrijden binnen zijn gilde heeft gewonnen, maar hij ontving ook lof van onze Koning Leoric zelf - moge zijn ziel in vrede rusten.  Griswold is ook een groot held; vraag het Cain maar. |" },
	{ 183, "Cain is de verhalenverteller van Tristram zolang ik mij kan herinneren.  Hij weet zoveel, en kan u vrijwel alles vertellen over bijna alles. |" },
	{ 184, "Farnham is een dronkaard die zijn buik met bier vult en ieders oren met onzin. \n \nIk weet dat zowel Pepin als Ogden medelijden met hem heeft, maar ik word er zo moedeloos van hem elke avond verder en verder in een beneveld stupor te zien wegzakken. |" },
	{ 185, "Pepin heeft het leven van mijn grootmoeder gered, en ik weet dat ik hem dat nooit kan vergelden.  Zijn vermogen elke ziekte te genezen is krachtiger dan het machtigste zwaard en mysterieuzer dan welke spreuk u ook kunt noemen.  Als u ooit genezing behoeft, kan Pepin u helpen. |" },
	{ 186, "Ik groeide op met Wirts moeder, Canace.  Hoewel zij slechts licht gewond raakte toen die afzichtelijke wezens hem stalen, herstelde zij nooit.  Ik denk dat zij aan een gebroken hart is gestorven.  Wirt is een hardvochtige jongeman geworden die er alleen op uit is te profiteren van het zweet van anderen.  Ik weet dat hij geleden heeft en gruwelen heeft gezien die ik mij niet eens kan voorstellen, maar iets van die duisternis hangt nog altijd om hem heen. |" },
	{ 187, "Ogden en zijn vrouw hebben mij en mijn grootmoeder in hun huis opgenomen en mij zelfs een paar goudstukken laten verdienen door in de herberg te werken.  Ik ben hun zoveel verschuldigd, en hoop op een dag deze plek te verlaten en hun te helpen een groots hotel in het oosten te beginnen. |" },
	{ 188, "Wel, wat kan ik voor je doen? |" },
	{ 189, "Als je een goed wapen zoekt, laat me je dit eens zien.  Neem je gewone stompe wapen, zoals een strijdknots.  Werkt voortreffelijk tegen de meeste van die onsterfelijke gruwelen daarbeneden, en er is niets beters om magere kleine skeletten te verbrijzelen! |" },
	{ 190, "De bijl?  Ja, dat is een goed wapen, in evenwicht tegen elke vijand.  Kijk hoe hij de lucht klieft, en stel je dan een lekkere dikke demonenkop op zijn pad voor.  Bedenk wel dat hij traag zwaait - maar wat een zware slag! |" },
	{ 191, "Kijk naar die snede, dat evenwicht.  Een zwaard in de juiste handen, en tegen de juiste vijand, is de meester van alle wapens.  Zijn scherpe kling vindt op ondoden weinig te hakken of te doorboren, maar tegen een levende, ademende vijand snijdt een zwaard hun vlees beter open! |" },
	{ 192, "Je wapens en harnas zullen de sporen van je strijd tegen de Duisternis tonen.  Als je ze naar mij brengt, kan ik ze met wat werk en een hete smidse weer in topvorm brengen. |" },
	{ 193, "Terwijl ik de metalen en het gereedschap dat ik nodig heb praktisch moet binnensmokkelen via karavanen die de randen van onze verdoemde stad schampen, lijkt die heks, Adria, altijd te krijgen wat zij nodig heeft.  Als ik ook maar het kleinste beetje wist over hoe je magie zo aanwendt als zij, zou ik werkelijk ongelooflijke dingen kunnen maken. |" },
	{ 194, "Gillian is een aardige meid.  Jammer dat haar grootje in zo'n slechte gezondheid verkeert, anders zou ik regelen dat zij beiden hier wegkwamen met een van de handelskaravanen. |" },
	{ 195, "Soms denk ik dat Cain te veel praat, maar ik neem aan dat dat zijn roeping in het leven is.  Als ik staal zo goed kon buigen als hij je oor kan buigen, zou ik een hofharnas kunnen maken dat een Keizer waardig is! |" },
	{ 196, "Ik was bij Farnham die nacht dat Lazarus ons het Labyrint in leidde.  Ik heb de Aartsbisschop nooit teruggezien, en ik had het misschien niet overleefd als Farnham niet aan mijn zijde was geweest.  Ik vrees dat de aanval zijn ziel even kreupel heeft gemaakt als, wel, iets anders mijn been.  Ik kan deze strijd nu niet voor hem voeren, maar ik zou het doen als ik kon. |" },
	{ 197, "Een goed man die de noden van anderen boven zijn eigen stelt.  Je vindt in Tristram niemand meer - of waar dan ook - die een kwaad woord over de heler zegt. |" },
	{ 198, "Die knaap haalt zich nog eens ernstige moeilijkheden op de hals...  of eigenlijk moet ik zeggen: opnieuw.  Ik heb geprobeerd hem te interesseren voor werk hier en een eerlijk vak, maar hij verkiest de hoge winsten van handel in waren van dubieuze herkomst.  Ik kan hem dat niet aanrekenen na wat hem is overkomen, maar ik zou willen dat hij tenminste voorzichtig was. |" },
	{ 199, "De herbergier heeft weinig klandizie en geen echte manier om winst te maken.  Hij weet de eindjes aan elkaar te knopen door eten en onderdak te bieden aan hen die af en toe door het dorp trekken, maar die glippen 's nachts even vaak weg als dat zij betalen.  Ware het niet om de voorraden graan en gedroogd vlees die hij in zijn kelder hield, dan waren de meesten van ons verhongerd in dat eerste jaar toen het hele platteland door demonen werd overspoeld. |" },
	{ 200, "Kan een kerel niet in vrede drinken? |" },
	{ 201, "Dat meisje dat de drankjes brengt?  O ja, wat een mooie dame.  Ook zo aardig. |" },
	{ 202, "Waarom doet dat ouwe kreng niet 's een keer wat.  Zeker, zeker, ze heeft spullen, maar luister nou 's naar mij...  ze is onnatuurlijk.  Ik heb 'r nog nooit zien eten of drinken - en je kan niemand vertrouwen die niet tenminste een beetje drinkt. |" },
	{ 203, "Cain is niet wat-ie zegt dat-ie is.  Zeker, zeker, hij vertelt een mooi verhaal...  sommige zijn echt eng of grappig...  maar ik denk dat-ie meer weet dan dat-ie weet dat-ie weet. |" },
	{ 204, "Griswold?  Goeie ouwe Griswold.  Ik hou van 'm als een broer!  We vochten samen, weet je, toen...  wij...  Lazarus...  Lazarus...  Lazarus!!! |" },
	{ 205, "Hehehe, ik mag Pepin wel.  Hij doet echt z'n best, weet je.  Luister 's, je moet zorgen dat je 'm leert kennen.  Goeie kerel zoals hij met mensen die altijd hulp willen.  H\xe9, dat lijkt wel een beetje op jou, h\xe8 held?  Ik was ook 's een held... |" },
	{ 206, "Wirt is een joch met meer problemen dan zelfs ik, en ik weet alles van problemen.  Luister 's - dat joch heeft een mooi handeltje, maar hij is er geweest, weet je?  Been kwijt!  Moet rondlopen op een stuk hout.  Zo triest, zo triest... |" },
	{ 207, "Ogden is de beste man van de stad.  Ik denk niet dat z'n vrouw me erg mag, maar zolang ze vaten blijft aanslaan, vind ik 'r best aardig.  Lijkt wel of ik meer tijd met Ogden heb doorgebracht dan met de meesten, maar hij is zo goed voor me... |" },
	{ 208, "Ik wil je wat vertelle', want ik weet alles van dit spul.  Da's m'n specialiteit.  Dit hier is 't beste...  h\xe9\xe9\xe9\xe9\xe9t beste!  Dat andere bier deugt niet meer sinds die stomme honden... |" },
	{ 209, "Niemand lui...  luistert ooit naar mij.  Ergens - ik weet 't niet zeker - maar ergens onder de kerk ligt een hele berg goud.  Glimmend en glanzend en gewoon wachtend tot iemand 't pakt. |" },
	{ 210, "Ik weet dat je je eigen idee\xebn hebt, en ik weet dat je dit niet gaat geloven, maar dat wapen dat je daar hebt - dat deugt gewoon niet tegen die grote bruten!  O, 't kan me niet schelen wat Griswold zegt, ze kunnen niks meer maken zoals vroeger... |" },
	{ 211, "Als ik jou was...  en dat ben ik niet...  maar als ik het was, zou ik al dat spul dat je hebt verkopen en hier weggaan.  Dat joch daarbuiten...  Hij heeft altijd wel wat goeds, maar je moet 'm wat goud geven anders laat-ie niet eens zien wat-ie heeft. |" },
	{ 212, "Ik bespeur een ziel op zoek naar antwoorden... |" },
	{ 213, "Wijsheid wordt verdiend, niet geschonken.  Als u een foliant van kennis ontdekt, verslind dan haar woorden.  Mocht u de arcane mysteri\xebn die in een boek staan al kennen, bedenk dan - die graad van meesterschap kan altijd nog toenemen. |" },
	{ 214, "De grootste macht is vaak de kortstlevende.  U kunt oude woorden van macht vinden, geschreven op perkamenten rollen.  De kracht van deze rollen ligt in het vermogen van zowel leerling als adept om ze met gelijke bekwaamheid uit te spreken.  Hun zwakte is dat zij eerst hardop gelezen moeten worden en nooit in uw geest gereed gehouden kunnen worden.  Weet ook dat deze rollen slechts eenmaal gelezen kunnen worden, dus gebruik ze met zorg. |" },
	{ 215, "Hoewel de hitte van de zon niet te meten is, is de enkele vlam van een kaars van groter gevaar.  Geen energie, hoe groot ook, kan zonder de juiste focus worden aangewend.  Voor vele spreuken kunnen betoverde Staven vele malen met magische energie worden geladen.  Ik heb het vermogen hun macht te herstellen - maar weet dat niets zonder prijs geschiedt. |" },
	{ 216, "De som van onze kennis ligt in de som van haar mensen.  Mocht u een boek of reliek vinden dat u niet kunt ontcijferen, aarzel dan niet het mij te brengen.  Als ik er wijs uit kan worden, zal ik delen wat ik vind. |" },
	{ 217, "Voor een man die slechts IJzer kent, bestaat er geen grotere magie dan Staal.  De smid Griswold is meer tovenaar dan hij weet.  Zijn vermogen vuur en metaal te versmelten is in dit land onge\xebvenaard. |" },
	{ 218, "Verdorvenheid bezit de kracht van bedrog, maar onschuld bezit de macht van zuiverheid.  De jonge vrouw Gillian heeft een zuiver hart en stelt de noden van haar grootmoeder boven de hare.  Zij vreest mij, maar dat komt slechts doordat zij mij niet begrijpt. |" },
	{ 219, "Een kist die in duisternis geopend wordt bevat geen grotere schat dan wanneer zij in het licht geopend wordt.  De verhalenverteller Cain is een raadsel, maar slechts voor hen die niet kijken.  Zijn kennis van wat onder de kathedraal ligt is veel groter dan hij zichzelf toestaat te beseffen. |" },
	{ 220, "Hoe hoger u uw vertrouwen in \xe9\xe9n man stelt, hoe dieper het moet vallen.  Farnham heeft zijn ziel verloren, maar niet aan een demon.  Zij ging verloren toen hij zijn medeburgers verraden zag worden door Aartsbisschop Lazarus.  Er valt kennis bij hem te vergaren, maar u moet feit van verbeelding scheiden. |" },
	{ 221, "De hand, het hart en de geest kunnen wonderen verrichten wanneer zij in volmaakte harmonie zijn.  De heler Pepin ziet in het lichaam op een wijze die zelfs ik niet vermag.  Zijn vermogen zieken en gewonden te herstellen wordt vergroot door zijn begrip van het maken van elixers en dranken.  Hij is de grootste bondgenoot die u in Tristram hebt. |" },
	{ 222, "Er is veel aan de toekomst dat wij niet kunnen zien, maar wanneer zij komt zullen het de kinderen zijn die haar hanteren.  De jongen Wirt heeft een zwartheid op zijn ziel, maar hij vormt geen bedreiging voor de stad of haar mensen.  Zijn heimelijke handel met de straatjongens en onuitgesproken gilden van nabijgelegen steden verschaft hem toegang tot vele voorwerpen die in Tristram niet gemakkelijk te vinden zijn.  Hoewel zijn methoden laakbaar mogen zijn, kan Wirt bijstand verlenen in uw strijd tegen de oprukkende Duisternis. |" },
	{ 223, "Aarden muren en een rieten dak maken nog geen thuis.  De herbergier Ogden dient in deze stad een groter doel dan velen beseffen.  Hij biedt onderdak aan Gillian en haar grootmoeder, onderhoudt wat Farnham nog aan leven rest, en biedt allen die in de stad zijn achtergebleven een anker naar wat Tristram eens was.  Zijn herberg, en de eenvoudige genoegens die daar nog te vinden zijn, geven een glimp van een leven dat de mensen hier zich herinneren.  Het is die herinnering die hun hoop op uw succes blijft voeden. |" },
	{ 224, "Psst...  hierheen... |" },
	{ 225, "Niet iedereen in Tristram heeft nut - of een markt - voor alles wat je in het labyrint zult vinden.  Zelfs ik niet, hoe moeilijk dat ook te geloven is. \n \nSoms zul jij alleen een doel voor sommige dingen kunnen vinden. |" },
	{ 226, "Geloof niet alles wat de dronkaard zegt.  Te veel bier heeft zijn zicht en zijn gezond verstand vertroebeld. |" },
	{ 227, "Voor het geval het je niet is opgevallen: ik koop niets uit Tristram.  Ik ben een importeur van kwaliteitswaren.  Als je rommel wilt slijten, moet je bij Griswold, Pepin of die heks, Adria, zijn.  Ik weet zeker dat zij alles wat je hun kunt brengen gretig zullen inpikken... |" },
	{ 228, "Ik neem aan dat ik de smid mijn leven verschuldigd ben - voor zover dat wat voorstelt.  Zeker, Griswold bood mij een leerlingplaats in de smidse aan, en hij is een aardige vent, maar ik zal nooit genoeg geld krijgen om...  wel, laten we zeggen dat ik vaste plannen heb die een grote hoeveelheid goud vereisen. |" },
	{ 229, "Als ik een paar jaar ouder was, zou ik haar overladen met alle rijkdom die ik bijeen kon brengen, en ik verzeker je dat ik aan zeer mooie spullen kan komen.  Gillian is een prachtig meisje dat uit Tristram weg zou moeten zodra het veilig is.  Hmmm...  misschien neem ik haar wel mee als ik ga... |" },
	{ 230, "Cain weet te veel.  Hij jaagt me de stuipen op het lijf - nog meer dan die vrouw aan de overkant van de rivier.  Hij blijft me maar vertellen hoe gelukkig ik ben dat ik leef, en hoe mijn verhaal in de legende voorspeld is.  Ik denk dat hij niet goed snik is. |" },
	{ 231, "Farnham - dat is nog eens een man met ernstige problemen, en ik weet alles over hoe ernstig problemen kunnen zijn.  Hij vertrouwde te veel op de integriteit van \xe9\xe9n man, en Lazarus leidde hem regelrecht in de muil van de dood.  O, ik weet hoe het daarbeneden is, dus begin me niet eens te vertellen over je plannen om het kwaad te vernietigen dat in dat Labyrint huist.  Let gewoon op je benen... |" },
	{ 232, "Zolang je niets hoeft te laten vastzetten, is ouwe Pepin zo goed als ze komen. \n \nAls ik een paar van die dranken had gehad die hij brouwt, had ik misschien nog mijn been gehad... |" },
	{ 233, "Adria zit me echt dwars.  Zeker, Cain is griezelig in wat hij je over het verleden kan vertellen, maar die heks kan in jouw verleden kijken.  En zij weet ook altijd wel een manier om te krijgen wat zij nodig heeft.  Adria krijgt meer koopwaar in handen dan ik door de poorten van de Koninklijke Bazaar heb zien gaan tijdens het Hoogfeest. |" },
	{ 234, "Ogden is een dwaas dat hij hier blijft.  Ik zou hem voor een zeer redelijke prijs de stad uit kunnen krijgen, maar hij staat erop het met die stomme herberg te blijven proberen.  Ik neem aan dat hij Gillian tenminste een plek geeft om te werken, en zijn vrouw Garda maakt wel een voortreffelijke herderspastei... |" },
	{ 235, "Voorbij de Zaal der Helden ligt de Kamer van Been.  Eeuwige dood wacht ieder die de schatten zou willen stelen die in deze kamer verzegeld zijn.  Zo spreekt de Heer van Verschrikking, en zo staat het geschreven. |" },
	{ 236, "...en zo wacht Moed, gesloten voorbij de Poort van Bloed en voorbij de Zaal van Vuur, tot de Held van het Licht ontwaakt... |" },
	{ 237, "Ik zie wat u niet zien kunt.\nZicht vertroebelt, oog verstompt.\nDraait u om, dan zijn zij heen,\nfluisterend hun lied alleen.\nDan ziet u wat niet bestaat,\nschaduw waar het licht toch staat.\nUit de duisternis, uit de zin,\ngeworpen in de Hallen der Blinden. |\n" },
	{ 238, "De wapenkamers van de Hel zijn het thuis van de Krijgsheer van Bloed.  In zijn kielzog liggen de verminkte lichamen van duizenden.  Engelen en mensen zijn gelijkelijk neergemaaid om zijn eindeloze offers te vervullen aan de Duisteren die om \xe9\xe9n ding schreeuwen - bloed. |" },
	{ 239, "Voorbij de Zaal der Helden ligt de Kamer van Been.  Eeuwige dood wacht ieder die de schatten zou willen stelen die in deze kamer verzegeld zijn.  Zo spreekt de Heer van Verschrikking, en zo staat het geschreven. |" },
	{ 240, "...en zo wacht Moed, gesloten voorbij de Poort van Bloed en voorbij de Zaal van Vuur, tot de Held van het Licht ontwaakt... |" },
	{ 241, "Ik zie wat u niet zien kunt.\nZicht vertroebelt, oog verstompt.\nDraait u om, dan zijn zij heen,\nfluisterend hun lied alleen.\nDan ziet u wat niet bestaat,\nschaduw waar het licht toch staat.\nUit de duisternis, uit de zin,\ngeworpen in de Hallen der Blinden. |\n" },
	{ 242, "De wapenkamers van de Hel zijn het thuis van de Krijgsheer van Bloed.  In zijn kielzog liggen de verminkte lichamen van duizenden.  Engelen en mensen zijn gelijkelijk neergemaaid om zijn eindeloze offers te vervullen aan de Duisteren die om \xe9\xe9n ding schreeuwen - bloed. |" },
	{ 243, "Voorbij de Zaal der Helden ligt de Kamer van Been.  Eeuwige dood wacht ieder die de schatten zou willen stelen die in deze kamer verzegeld zijn.  Zo spreekt de Heer van Verschrikking, en zo staat het geschreven. |" },
	{ 244, "...en zo wacht Moed, gesloten voorbij de Poort van Bloed en voorbij de Zaal van Vuur, tot de Held van het Licht ontwaakt... |" },
	{ 245, "Ik zie wat u niet zien kunt.\nZicht vertroebelt, oog verstompt.\nDraait u om, dan zijn zij heen,\nfluisterend hun lied alleen.\nDan ziet u wat niet bestaat,\nschaduw waar het licht toch staat.\nUit de duisternis, uit de zin,\ngeworpen in de Hallen der Blinden. |\n" },
	{ 246, "De wapenkamers van de Hel zijn het thuis van de Krijgsheer van Bloed.  In zijn kielzog liggen de verminkte lichamen van duizenden.  Engelen en mensen zijn gelijkelijk neergemaaid om zijn eindeloze offers te vervullen aan de Duisteren die om \xe9\xe9n ding schreeuwen - bloed. |" },
	{ 249, "Neem ter harte en wees getuige van de waarheden die hierin liggen, want zij zijn de laatste nalatenschap van de Horadrim.  Er woedt zelfs nu nog een oorlog, voorbij de velden die wij kennen - tussen de utopische koninkrijken van de Hoge Hemelen en de chaotische kuilen van de Brandende Hellen.  Deze oorlog staat bekend als het Grote Conflict, en zij woedt en brandt langer dan enige ster aan de hemel.  Geen van beide zijden krijgt lang de overhand, terwijl de krachten van Licht en Duisternis voortdurend strijden om de heerschappij over de gehele schepping. |" },
	{ 250, "Neem ter harte en wees getuige van de waarheden die hierin liggen, want zij zijn de laatste nalatenschap van de Horadrim.  Wanneer het Eeuwige Conflict tussen de Hoge Hemelen en de Brandende Hellen op sterfelijke bodem valt, wordt het de Zondeoorlog genoemd.  Engelen en Demonen wandelen vermomd onder de mensheid en vechten in het geheim, weg van de nieuwsgierige ogen van stervelingen.  Sommige vermetele, machtige stervelingen hebben zich zelfs bij een van beide zijden aangesloten en hielpen de loop van de Zondeoorlog bepalen. |" },
	{ 251, "Neem ter harte en wees getuige van de waarheden die hierin liggen, want zij zijn de laatste nalatenschap van de Horadrim.  Bijna driehonderd jaar geleden werd bekend dat de Drie Oerkwaden van de Brandende Hellen op raadselachtige wijze naar onze wereld waren gekomen.  De Drie Broeders teisterden decennialang de landen van het oosten, terwijl de mensheid bevend in hun kielzog achterbleef.  Onze Orde - de Horadrim - werd gesticht door een groep geheimzinnige magi\xebrs om de Drie Kwaden voorgoed op te jagen en te vangen.\n \nDe oorspronkelijke Horadrim vingen twee van de Drie in machtige voorwerpen die Zielsstenen heten en begroeven hen diep onder de verlaten oostelijke zanden.  Het derde Kwaad ontkwam aan gevangenschap en vluchtte naar het westen met vele Horadrim in achtervolging.  Het Derde Kwaad - bekend als Diablo, de Heer van Verschrikking - werd uiteindelijk gevangen, zijn essentie in een Zielssteen gezet en binnen dit Labyrint begraven.\n \nWees gewaarschuwd dat de zielssteen verborgen moet blijven voor hen die niet van het geloof zijn.  Zou Diablo worden vrijgelaten, dan zou hij een lichaam zoeken dat gemakkelijk te beheersen is, want hij zou zeer zwak zijn - wellicht dat van een oude man of een kind. |" },
	{ 252, "Zo geschiedde het dat er een grote omwenteling plaatsvond in de Brandende Hellen, bekend als de Duistere Verbanning.  De Mindere Kwaden wierpen de Drie Oerkwaden omver en verbanden hun geestesvormen naar het sterfelijke rijk.  De demonen Belial (de Heer van Leugens) en Azmodan (de Heer van Zonde) streden om de heerschappij over de Hel tijdens de afwezigheid van de Drie Broeders.  De hele Hel raakte verdeeld tussen de facties van Belial en Azmodan, terwijl de krachten van de Hoge Hemelen voortdurend op de Poorten van de Hel zelf beukten. |" },
	{ 253, "Vele demonen reisden naar het sterfelijke rijk op zoek naar de Drie Broeders.  Deze demonen werden naar het sterfelijke vlak gevolgd door Engelen die hen door de uitgestrekte steden van het Oosten opjoegen.  De Engelen verbonden zich met een geheimzinnige Orde van sterfelijke magi\xebrs, de Horadrim genaamd, die snel bedreven raakten in de demonenjacht.  Zij maakten ook vele duistere vijanden in de onderwerelden. |" },
	{ 254, "Zo geschiedde het dat de Drie Oerkwaden in geestesvorm naar het sterfelijke rijk werden verbannen, en nadat zij decennialang chaos over het Oosten hadden gezaaid, werden zij opgejaagd door de vervloekte Orde van de sterfelijke Horadrim.  De Horadrim gebruikten voorwerpen die Zielsstenen heten om de essentie te bevatten van Mephisto, de Heer van Haat, en zijn broer Baal, de Heer van Vernietiging.  De jongste broer - Diablo, de Heer van Verschrikking - ontkwam naar het westen.\n \nUiteindelijk vingen de Horadrim ook Diablo in een Zielssteen, en begroeven hem onder een oude, vergeten Kathedraal.  Daar slaapt de Heer van Verschrikking en wacht op de tijd van zijn wedergeboorte.  Weet dat hij een lichaam van jeugd en macht zal zoeken om te bezitten - een dat onschuldig is en gemakkelijk te beheersen.  Dan zal hij opstaan om zijn Broeders te bevrijden en opnieuw de vlammen van de Zondeoorlog aan te wakkeren... |" },
	{ 255, "Alle lof aan Diablo - Heer van Verschrikking en Overlevende van de Duistere Verbanning.  Toen hij uit zijn lange sluimer ontwaakte, sprak mijn Heer en Meester tot mij van geheimen die weinig stervelingen kennen.  Hij vertelde mij dat de koninkrijken van de Hoge Hemelen en de kuilen van de Brandende Hellen een eeuwige oorlog voeren.  Hij onthulde de machten die deze tweedracht in de rijken der mensen hebben gebracht.  Mijn heer heeft de strijd om deze wereld en allen die hier bestaan de Zondeoorlog genoemd. |" },
	{ 256, "Roem en Lof aan Diablo - Heer van Verschrikking en Leider der Drie.  Mijn Heer sprak tot mij van zijn twee Broeders, Mephisto en Baal, die lang geleden naar deze wereld werden verbannen.  Mijn Heer wenst zijn tijd af te wachten en zijn ontzagwekkende macht aan te wenden opdat hij zijn gevangen broeders kan bevrijden uit hun tomben onder de zanden van het oosten.  Zodra mijn Heer zijn Broeders vrijlaat, zal de Zondeoorlog opnieuw de woede der Drie kennen. |" },
	{ 257, "Heil en Offer aan Diablo - Heer van Verschrikking en Vernietiger van Zielen.  Toen ik mijn Meester uit zijn slaap wekte, trachtte hij de gedaante van een sterveling te bezitten.  Diablo poogde het lichaam van Koning Leoric op te eisen, maar mijn Meester was te zwak door zijn gevangenschap.  Mijn Heer had een eenvoudig en onschuldig anker naar deze wereld nodig, en bevond de jongen Albrecht volmaakt voor die taak.  Terwijl de goede Koning Leoric krankzinnig achterbleef door Diablo's mislukte bezetenheid, ontvoerde ik zijn zoon Albrecht en bracht hem voor mijn Meester.  Ik wacht nu op Diablo's roep en bid dat ik beloond zal worden wanneer hij eindelijk als Heer van deze wereld te voorschijn treedt. |" },
	{ 258, "Goddank bent u teruggekeerd!\nEr is veel veranderd sinds u hier woonde, mijn vriend.  Alles was vredig tot de duistere ruiters kwamen en ons dorp vernietigden.  Velen werden neergemaaid waar zij stonden, en zij die de wapens opnamen werden gedood of weggesleept om slaaf te worden - of erger.  De kerk aan de rand van de stad is ontheiligd en wordt gebruikt voor duistere rituelen.  De kreten die 's nachts weerklinken zijn onmenselijk, maar sommigen van onze dorpelingen leven wellicht nog.  Volg het pad tussen mijn herberg en de smidse om de kerk te vinden en te redden wie u kunt. \n \nWellicht kan ik u meer vertellen als wij opnieuw spreken.  Veel geluk.|" },
	{ 259, "Voorbij de Zaal der Helden ligt de Kamer van Been.  Eeuwige dood wacht ieder die de schatten zou willen stelen die in deze kamer verzegeld zijn.  Zo spreekt de Heer van Verschrikking, en zo staat het geschreven. |" },
	{ 260, "...en zo wacht Moed, gesloten voorbij de Poort van Bloed en voorbij de Zaal van Vuur, tot de Held van het Licht ontwaakt... |" },
	{ 261, "Ik zie wat u niet zien kunt.\nZicht vertroebelt, oog verstompt.\nDraait u om, dan zijn zij heen,\nfluisterend hun lied alleen.\nDan ziet u wat niet bestaat,\nschaduw waar het licht toch staat.\nUit de duisternis, uit de zin,\ngeworpen in de Hallen der Blinden. |\n" },
	{ 262, "De wapenkamers van de Hel zijn het thuis van de Krijgsheer van Bloed.  In zijn kielzog liggen de verminkte lichamen van duizenden.  Engelen en mensen zijn gelijkelijk neergemaaid om zijn eindeloze offers te vervullen aan de Duisteren die om \xe9\xe9n ding schreeuwen - bloed. |" },
	{ 263, "Voorbij de Zaal der Helden ligt de Kamer van Been.  Eeuwige dood wacht ieder die de schatten zou willen stelen die in deze kamer verzegeld zijn.  Zo spreekt de Heer van Verschrikking, en zo staat het geschreven. |" },
	{ 264, "...en zo wacht Moed, gesloten voorbij de Poort van Bloed en voorbij de Zaal van Vuur, tot de Held van het Licht ontwaakt... |" },
	{ 265, "Ik zie wat u niet zien kunt.\nZicht vertroebelt, oog verstompt.\nDraait u om, dan zijn zij heen,\nfluisterend hun lied alleen.\nDan ziet u wat niet bestaat,\nschaduw waar het licht toch staat.\nUit de duisternis, uit de zin,\ngeworpen in de Hallen der Blinden. |\n" },
	{ 266, "De wapenkamers van de Hel zijn het thuis van de Krijgsheer van Bloed.  In zijn kielzog liggen de verminkte lichamen van duizenden.  Engelen en mensen zijn gelijkelijk neergemaaid om zijn eindeloze offers te vervullen aan de Duisteren die om \xe9\xe9n ding schreeuwen - bloed. |" },
	{ 267, "U moet de twee demonen vernietigen die Horazon binnen zijn Heiligdom gevangen houdt, koste wat kost!  Mochten zij aan hun gevangenschap ontsnappen, dan zullen zij een verbinding met deze wereld scheppen die wat onder de Kathedraal ligt op een kindersprookje zal doen lijken. |" },
	{ 268, "Een gedurfd verhaal inderdaad!  Mijn beperkte tijd onder de Kathedraal maakt mij slecht toegerust om u hierbij te helpen, maar zoals altijd zult u Cain goed onderlegd vinden in legenden en volksverhalen. |" },
	{ 269, "Horazon was krankzinnig!  Er zijn krachten waarmee men zich niet bemoeit!  Het zou mij niet verbazen als u slechts de verkoolde resten van deze verdomde dwaas zou vinden! |" },
	{ 270, "0-crimson.TRN" },
	{ 271, "Dat klinken inderdaad als duistere wezens.  Ik ben onwetend in zaken van deze aard, maar ik neem aan dat onze verhalenverteller zulke legenden kent. |" },
	{ 272, "Zo, u zoekt kennis over de oorlogen van de Hel?  Cryptische folianten spreken van grote veldslagen die bepaalden wie van de demonenheren over de Hel zou heersen.  Zij vermelden ook een bittere rivaliteit tussen twee van deze heren - Azmodan, die de Gehoornde Dood tegen de legers van het licht aanvoerde, en Belial, bekend als de Heer van Leugens.  Hun haat jegens elkaar is eeuwig, de redenen voor hun afkeer - zelfs voor henzelf verloren. \n \nEr gaan verhalen dat de waanzinnige tovenaar Horazon de luitenants van deze twee helheren op de een of andere manier in zijn heiligdom gevangen zette.  Er kan geen gevaarlijker pad zijn dan dat wat naast demonen loopt.  Mocht u ook dit pad zoeken, bewaak dan uw leven...  en uw ziel...  zeer zorgvuldig, mijn vriend. |" },
	{ 273, "Je gaat op een demon jagen, is dat wat je zei?  Ik weet dat ik dat niet gehoord heb, want niemand jaagt op demonen, nee.  Niemand! |" },
	{ 274, "Een schatkaart?  Hebt u die bij u?  Laat eens zien!  Hmm, hij ziet er behoorlijk oud uit, en sommige gebouwen in de stad staan niet op deze kaart.  O, ik wou dat ik met u mee kon om de schat te zoeken, maar ik moet straks aan het werk. |" },
	{ 275, "Het verzorgen en voeden van demonen behoort beslist NIET tot mijn interesses.  Hier is een vriendelijk advies: als je de kans krijgt, dood dan ALLES wat je daarbeneden ziet. |" },
	{ 276, "0-crimson.TRN" },
	{ 277, "Zo, u bent de held over wie iedereen praat.  Zou u een arme, eenvoudige boer wellicht uit een vreselijke ellende kunnen helpen?  Aan de rand van mijn boomgaard, net ten zuiden van hier, zwelt er iets afschuwelijks uit de grond!  Ik kan niet bij mijn gewassen of mijn hooibalen, en mijn arme koeien zullen verhongeren.  De heks gaf mij dit en zei dat het dat ding uit mijn veld zou blazen.  Als u het zou kunnen vernietigen, zou ik u eeuwig dankbaar zijn.  Ik zou het zelf doen, maar iemand moet hier bij de koeien blijven...|" },
	{ 278, "Farmer's speech from HF is unused now" },
	{ 279, "Is het weg?  Hebt u het teruggestuurd naar de duistere krochten van Hades die het hebben voortgebracht?  U wat?  O, zeg mij niet dat u het kwijt bent!  Zulke dingen zijn niet goedkoop, weet u.  U moet het vinden en dan die gruwel uit onze stad blazen.|" },
	{ 280, "Ik hoorde de explosie tot hier!  Veel dank, vriendelijke vreemdeling.  Met al die dingen die uit de grond komen, monsters die de kerk overnemen enzovoort zijn dit zware tijden.  Ik ben maar een arme boer, maar hier -- neem dit met mijn grote dank aan.|" },
	{ 281, "O, wat een ellende heb ik...  misschien...  Nee, ik kan het u niet aandoen, met al die andere ellende.  Misschien kunt u terugkomen nadat u de kerk van een paar van die wezens hebt gezuiverd...  en wat tijd vrijmaken om een arme boer te helpen?|" },
	{ 282, "Ik heb werkelijk geen tijd om over een of andere kaart te praten die u zoekt.  Ik heb veel zieke mensen die mijn hulp nodig hebben, en de uwe ook.|" },
	{ 283, "Ik ben Theo kwijt!  Ik ben mijn beste vriend kwijt!  We speelden bij de rivier, en Theo zei dat hij naar dat grote groene ding wilde gaan kijken.  Ik zei dat we dat niet moesten doen, maar we slopen erheen, en toen kwam er ineens een BEEST uit!  We renden weg maar Theo viel en het beest GREEP hem en nam hem mee!|" },
	{ 284, "Hebt u hem gevonden?  U moet Theodore vinden, alstublieft!  Hij is nog maar klein.  Hij kan niet voor zichzelf zorgen!  Alstublieft!|" },
	{ 285, "U hebt hem gevonden!  U hebt hem gevonden!  Dank u!  O Theo, hebben die vieze beesten je bang gemaakt?  H\xe9!  Bah!  Er zit iets in je vacht!  Gadver!  Kom mee, Theo, we gaan naar huis!  Nogmaals bedankt, heldpersoon!|" },
	{ 286, "Wij hebben lang gesluimerd, en de tijd van ontwaken is gekomen.  Na onze lange slaap zijn wij vervuld van grote honger.  Spoedig, nu, zullen wij ons voeden...|" },
	{ 287, "Heb je je vermaakt, klein zoogdiertje?  Wat zielig.  Jullie kleine wereld zal geen enkele uitdaging vormen.|" },
	{ 288, "Deze landen zullen ontheiligd worden, en ons broedsel zal de velden overspoelen die mensen thuis noemen.  Onze ranken zullen deze wereld omhullen, en wij zullen ons te goed doen aan het vlees van haar bewoners.  De mens zal ons vee en ons voedsel worden.|" },
	{ 289, "Ah, ik kan je ruiken...  je bent dichtbij!  Dichtbij!  Ssss...  de geur van bloed en angst...  hoe verleidelijk...|" },
	{ 296, "Neem me niet kwalijk, maar hebt u gehoord wat er gaande is?  Enkele mannen zijn uit het dorp verdwenen.  Dica's zonen, Inaius en Ruphe, beweren enkele dagen geleden vreemde lichten diep in de bossen te hebben zien gloeien, maar sindsdien heeft niemand meer iets van hen vernomen.  Ook ik heb een karmozijnen schijnsel voorbij de essenbossen gezien, maar ik was te bang om het te naderen.  Ik vrees dat Ogden of onze heler Pepin de volgende kan zijn.  Wilt u alstublieft uitzoeken wat er is gebeurd? |" },
	{ 297, "Hebt u al onderzocht wat die vreemde lichten veroorzaakt?  Er worden meer mannen vermist sinds wij elkaar voor het laatst spraken, en ik begin te vrezen dat wij spoedig allen zullen verdwijnen. |" },
	{ 298, "Ik geef toe dat ook ik deze vreemde lichten heb gezien, maar ik voelde mij er niet toe aangetrokken.  Ik zal er zeker uit de buurt blijven, en ik zal iedereen die hier komt zeggen hetzelfde te doen. |" },
	{ 299, "Ruphe en Inaius worden vermist?  Het Licht beware ons!  Is er dan nergens een veilige plek?  Onze enige hoop op een terugkeer naar een vredig leven rust in u.  Alstublieft, u moet die jongens vinden en hen thuisbrengen bij hun familie. |" },
	{ 300, "Goede held, een ogenblik van uw tijd alstublieft.  Terwijl ik een van de dorpelingen verzorgde die behoorlijk ziek was geworden, viel mij iets vreemds op aan zijn huis.  Er kwamen vreemde geluiden en een ziekelijk zoete geur uit de kelder.  Denkend dat deze dampen wellicht met zijn ziekte te maken hadden, onderzocht ik het.  In zijn kelder waren monsterlijke wormen die zich vanuit de ondergrond omhoog wrongen en kronkelden.  Ik smeek u, dood deze wezens voordat zij hun weg naar de stad kunnen vinden.  Ik heb de deur van zijn huis voor u open gelaten.  Het is het huis tegenover het mijne. |" },
	{ 301, "Opnieuw hebt u deze nederige stad van het oprukkende kwaad gered.  Wij staan, zoals altijd, voor eeuwig bij u in het krijt. |" },
	{ 302, "Ik vrees dat de wormen het dorp spoedig kunnen overspoelen!  Ik weet dat zij omhoog komen uit het huis tegenover het mijne.  Alleen al de gedachte aan die slijmerige beesten die mijn huis in sijpelen maakt mij misselijk.  Alstublieft, verlos ons van hen. |" },
	{ 303, "Ik heb zoiets niet in mijn winkel gezien, maar ik zal er goed op letten.  Misschien bevallen de vuren van mijn smidse hun niet als zij deze kant op komen. |" },
	{ 304, "Wormen die uit de grond oprijzen?  Veel van de oude geschriften spreken van giftige insecten en vuile wezens uit de luchten en de zee\xebn die de mensheid teisteren.  Het is geen verrassing dat de aarde zelf nu een soortgelijk gevaar voortbrengt, nu de bewoners van de onderwereld over ons zijn gekomen. |" },
	{ 305, "*kokhalzend* \n \nLuister, luister..\n \nIk hou niet eens van wormen.  \n \nVertel me niks over je wormen!  \n \nIk wil je wormen niet!  \n \nNee, nee bedankt!  \n \nGeen wormen voor mij... |" },
	{ 306, "Zoek de woning op waarheen Pepin de heler u heeft verwezen.  Daar zullen uw opdrachten duidelijk worden en uw middelen vanzelfsprekend. |" },
	{ 307, "Haha!  Laten ze je nu op wormen jagen?  \nWat volgt er, bladeren verzamelen?  Paddenstoelen plukken?  \n \nKijk, vriend, je hebt daar een hele kerk vol demonen om je zorgen over te maken.  Ik zie niet in hoe een paar kleine wormen zo erg kunnen zijn. |" },
	{ 308, "Dat klinkt behoorlijk walgelijk, en ik vrees dat ik niets over wormen heb gehoord.  Wellicht kan Cain de verhalenverteller van enig nut zijn. |" },
	{ 309, "Wacht, voordat u iets zegt: mijn grootmoeder droomde over reusachtige, kronkelende wezens.  Zij zag ook Pepin uit een huis in de stad wegrennen.  Denkt u dat dit iets betekent? |" },
	{ 310, "Sterveling, bevrijd mij uit mijn gevangenschap en uw beloning zal groter zijn dan u zich kunt voorstellen.  Lees het boek en ik zal vrijkomen.|" },
	{ 311, "Gillian blijft maar doorgaan over vreemde lichten in de bomen, maar ik kan er kop noch staart aan vastknopen.  Ik heb beslist geen vreemde lichten gezien, en als ik ze zag, zouden ze wel mijn minste zorg zijn. |" },
	{ 312, "Hoewel de schenkster soms wat verward lijkt, is het waar dat er mannen uit het dorp verdwijnen.  Het doet mij denken aan oude geschriften over een demonische verleidster genaamd Andariel.  Bekend als de Maagd der Kwelling, was haar dorst naar sterfelijk bloed zo groot dat zij een spreuk trachtte te leren om in het sterfelijke rijk door te dringen.  Door een van de duistere tovenaars van de onderwereld te verleiden, verkreeg Andariel de kennis die zij nodig had en zo begon zij sterfelijke mannen naar haar duistere hoek van de Hel te lokken.  Als deze legenden waar zijn, is zij geen wezen dat lichtvaardig moet worden opgevat. |" },
	{ 313, "*gesnurk* |" },
	{ 314, "Weet je, ik heb naar die lichten gezocht maar ik kan ze niet vinden.  Als Gillian zegt dat ze er zijn, eh, geloof ik haar, maar ik heb ze zelf nog niet gezien. |" },
	{ 315, "De Succubus is een demon die zich voedt met de essentie van sterfelijke mannen.  U zult merken dat Andariel een flinke eetlust heeft.  De stad zal spoedig van alle volwassen mannen ontdaan zijn tenzij u haar maaltijd nu stopt. |" },
	{ 316, "Demonen die de gedaante van mooie vrouwen aannemen, zegt u?  Dat is afschuwelijk!  Geloofd zij het licht dat u dit mysterie hebt opgelost voordat er nog meer van onze mannen de dood in werden gelokt.  Dank u dat u ons opnieuw veilig hebt gehouden voor de machten der duisternis. |" },
	{ 317, "Ik heb spreuken, bedreigingen, bezwering en onderhandeling met dit vuile wezen geprobeerd -- alles tevergeefs.  Mijn methoden om mindere demonen te knechten lijken geen enkel effect op dit vreeswekkende beest te hebben.|" },
	{ 318, "Mijn huis raakt langzaam bedorven door de verdorvenheid van deze ongewenste gevangene.  De crypten zijn	vol schaduwen die net buiten mijn gezichtsveld bewegen.  Het zwakke gekrab van klauwen danst aan de rand van mijn gehoor.  Zij zoeken, denk ik, naar dit dagboek.|" },
	{ 319, "In zijn geraaskal heeft het wezen zijn naam laten ontglippen -- Na-Krul.  Ik heb getracht de naam te onderzoeken, maar de kleinere demonen hebben mijn bibliotheek op de een of andere manier vernietigd.  Na-Krul...  De naam vervult mij met een koude vrees.  Ik denk er liever aan als Het Wezen dan dat ik over zijn ware naam peins.|" },
	{ 320, "Het gehuil van woede van het gevangen wezen belet mij de broodnodige slaap.  Het raast tegen degene die het naar de Leegte zond, en het roept vuile vervloekingen over mij af omdat ik het hier gevangen zette.  Zijn woorden vervullen mijn hart met verschrikking, en toch kan ik zijn stem niet buitensluiten.|" },
	{ 321, "Mijn tijd raakt snel op.  Ik moet de manieren optekenen om de demon te verzwakken, en die tekst dan verbergen, opdat zijn dienaren niet een manier vinden om mijn kennis te gebruiken om hun heer te bevrijden.  Ik hoop dat wie dit dagboek ook vindt, de kennis zal zoeken.|" },
	{ 322, "Wie deze rol vindt, is belast met het stoppen van het demonische wezen dat binnen deze muren ligt.  Mijn tijd is voorbij.  Zelfs nu klauwen zijn helse dienaren aan de breekbare deur waarachter ik mij verberg.  \n \nIk heb de demon met arcane magie verlamd en hem binnen grote muren opgesloten, maar ik vrees dat dat niet genoeg zal zijn. \n \nDe spreuken in mijn drie grimoires zullen u beschermde toegang tot zijn domein verschaffen, maar alleen als zij in de juiste volgorde worden uitgesproken.  De hendels bij de ingang zullen de barri\xe8res verwijderen en de demon bevrijden; raak ze niet aan!  Gebruik enkel deze spreuken om binnen te komen, anders kan zijn macht te groot zijn voor u om te verslaan.|" },
	{ 323, "In Spiritu Sanctum. |" },
	{ 324, "Praedictum Otium. |" },
	{ 325, "Efficio Obitus Ut Inimicus. |" },
	{ 326, "In Spiritu Sanctum. |" },
	{ 327, "Praedictum Otium. |" },
	{ 328, "Efficio Obitus Ut Inimicus. |" },
	{ 329, "In Spiritu Sanctum. |" },
	{ 330, "Praedictum Otium. |" },
	{ 331, "Efficio Obitus Ut Inimicus. |" },
	{ 332, "In Spiritu Sanctum. |" },
	{ 333, "Praedictum Otium. |" },
	{ 334, "Efficio Obitus Ut Inimicus. |" },
	{ 335, "In Spiritu Sanctum. |" },
	{ 336, "Praedictum Otium. |" },
	{ 337, "Efficio Obitus Ut Inimicus. |" },
	{ 338, "\\\"De luitenant van Belial staat bekend als Grimspike...\n \nHoed u voor deze demon, want zijn kracht lijkt onmetelijk...\n \nHet lezen van deze rol, en daarmee het uitspreken van zijn naam nabij een arcane cirkel van binding, zal hem daar zeker oproepen...\\\" |" },
	{ 339, "\\\"De luitenant van Belial staat bekend als Grimspike...\n \nHoed u voor deze demon, want zijn kracht lijkt onmetelijk...\n \nHet lezen van deze rol, en daarmee het uitspreken van zijn naam nabij een arcane cirkel van binding, zal hem daar zeker oproepen...\\\"\n \n \nHmm, nabij een cirkel van binding... |" },
	{ 340, "\\\"De luitenant van Belial staat bekend als Grimspike...\n \nHoed u voor deze demon, want zijn kracht lijkt onmetelijk...\n \nHet lezen van deze rol, en daarmee het uitspreken van zijn naam nabij een arcane cirkel van binding, zal hem daar zeker oproepen...\\\"\n \n \nHmm, nabij een cirkel van binding... |" },
	{ 341, "\\\"De luitenant van Belial staat bekend als Grimspike...\n \nHoed u voor deze demon, want zijn kracht lijkt onmetelijk...\n \nHet lezen van deze rol, en daarmee het uitspreken van zijn naam nabij een arcane cirkel van binding, zal hem daar zeker oproepen...\\\"\n \n \nHmm, nabij een cirkel van binding... |" },
	{ 342, "\\\"Het wezen van Vlam, door Horazon\\\".|" },
	{ 343, "\\\"Het wezen van Vlam, door Horazon\\\".\n \n \nZou interessante lectuur moeten zijn.|" },
	{ 344, "\\\"Het wezen van Vlam, door Horazon\\\".\n \n \nZou interessante lectuur moeten zijn.|" },
	{ 345, "\\\"Het wezen van Vlam, door Horazon\\\".\n \n \nZou interessante lectuur moeten zijn.|" },
	{ 346, "\\\"Dan wordt, door de geest aan de bewerkte steen te binden, hem leven gegeven.\\\" \n \n \nDit klinkt als een soort spreuk.|" },
	{ 347, "\\\"Dan wordt, door de geest aan de bewerkte steen te binden, hem leven gegeven.\\\" \n \n \nDit klinkt als een soort spreuk.|" },
	{ 348, "\\\"Dan wordt, door de geest aan de bewerkte steen te binden, hem leven gegeven.\\\" \n \n \nDit klinkt als een soort spreuk.|" },
	{ 349, "\\\"Dan wordt, door de geest aan de bewerkte steen te binden, hem leven gegeven.\\\" \n \n \nDit klinkt als een soort spreuk.|" },
	{ 350, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 351, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 352, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 353, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 354, "\\\"Het lijkt erop dat ik iets naar dit vlak heb gebracht dat zelfs ik niet kan beheersen.  Het wezen dat in mijn astrale val viel is een zeer dodelijke demon.  Ik heb het aan de bodem van de Kuil kunnen binden, maar het doodt alles wat ik erheen heb gestuurd in pogingen het te verslaan.  Hoewel het niet kan ontsnappen, verspert het wel de tunnels die naar mijn beschermde Toevlucht leiden.  Ik ben geneigd de hendel te gebruiken om de tunnels te openen om te zien of het gewoon weggaat, maar ik vrees dat het slimmer is dan de meeste mindere demonen die ik eerder heb gevangen.  Als ik het maar ergens anders heen kon lokken...\\\"|" },
	{ 355, "\\\"Het lijkt erop dat ik iets naar dit vlak heb gebracht dat zelfs ik niet kan beheersen.  Het wezen dat in mijn astrale val viel is een zeer dodelijke demon.  Ik heb het aan de bodem van de Kuil kunnen binden, maar het doodt alles wat ik erheen heb gestuurd in pogingen het te verslaan.  Hoewel het niet kan ontsnappen, verspert het wel de tunnels die naar mijn beschermde Toevlucht leiden.  Ik ben geneigd de hendel te gebruiken om de tunnels te openen om te zien of het gewoon weggaat, maar ik vrees dat het slimmer is dan de meeste mindere demonen die ik eerder heb gevangen.  Als ik het maar ergens anders heen kon lokken...\\\"|" },
	{ 356, "\\\"Het lijkt erop dat ik iets naar dit vlak heb gebracht dat zelfs ik niet kan beheersen.  Het wezen dat in mijn astrale val viel is een zeer dodelijke demon.  Ik heb het aan de bodem van de Kuil kunnen binden, maar het doodt alles wat ik erheen heb gestuurd in pogingen het te verslaan.  Hoewel het niet kan ontsnappen, verspert het wel de tunnels die naar mijn beschermde Toevlucht leiden.  Ik ben geneigd de hendel te gebruiken om de tunnels te openen om te zien of het gewoon weggaat, maar ik vrees dat het slimmer is dan de meeste mindere demonen die ik eerder heb gevangen.  Als ik het maar ergens anders heen kon lokken...\\\"|" },
	{ 357, "\\\"Het lijkt erop dat ik iets naar dit vlak heb gebracht dat zelfs ik niet kan beheersen.  Het wezen dat in mijn astrale val viel is een zeer dodelijke demon.  Ik heb het aan de bodem van de Kuil kunnen binden, maar het doodt alles wat ik erheen heb gestuurd in pogingen het te verslaan.  Hoewel het niet kan ontsnappen, verspert het wel de tunnels die naar mijn beschermde Toevlucht leiden.  Ik ben geneigd de hendel te gebruiken om de tunnels te openen om te zien of het gewoon weggaat, maar ik vrees dat het slimmer is dan de meeste mindere demonen die ik eerder heb gevangen.  Als ik het maar ergens anders heen kon lokken...\\\"|" },
	{ 358, "Laat deze foliant u tot waarschuwing dienen.  Dit is een verboden plaats.  Keer terug vanwaar u kwam en uw leven zal gespaard blijven.  Horazon, meester van de disciplines die wezens naar dit vlak oproepen en binden, belooft de dood aan hen die de vijf zuilen passeren.  U bent gewaarschuwd.|" },
	{ 359, "Laat deze foliant u tot waarschuwing dienen.  Dit is een verboden plaats.  Keer terug vanwaar u kwam en uw leven zal gespaard blijven.  Horazon, meester van de disciplines die wezens naar dit vlak oproepen en binden, belooft de dood aan hen die de vijf zuilen passeren.  U bent gewaarschuwd.|" },
	{ 360, "Laat deze foliant u tot waarschuwing dienen.  Dit is een verboden plaats.  Keer terug vanwaar u kwam en uw leven zal gespaard blijven.  Horazon, meester van de disciplines die wezens naar dit vlak oproepen en binden, belooft de dood aan hen die de vijf zuilen passeren.  U bent gewaarschuwd.|" },
	{ 361, "Laat deze foliant u tot waarschuwing dienen.  Dit is een verboden plaats.  Keer terug vanwaar u kwam en uw leven zal gespaard blijven.  Horazon, meester van de disciplines die wezens naar dit vlak oproepen en binden, belooft de dood aan hen die de vijf zuilen passeren.  U bent gewaarschuwd.|" },
	{ 362, "Klinkt als een goed idee.  Je kan maar beter meteeeen beginnen.|" },
	{ 363, "Dit gaat alles ver te boven wat ik ooit heb geleerd.  Ik kan slechts \xe9\xe9n persoon in heel Tristram bedenken die u zou kunnen helpen.  Cain, natuurlijk.|" },
	{ 364, "Neem me niet kwalijk, maar ik heb u iets te vertellen dat u interessant kunt vinden.  Het was het vreemdste ding.  Terwijl hij in de herberg zat te drinken, raaskalde Farnham over iets dat Azurewrath heet.  Hij zei ook iets over een gevallen engel.  Het was moeilijk hem te verstaan omdat hij erg dronken en verward was, maar ik meen mij iets te herinneren over een sleutel in een vat.  Hij bleef ook zijn gezicht bedekken en het woord 'Izual' steeds maar herhalen. |" },
	{ 365, "Weet u, nu ik erover nadenk, misschien was het geen sleutel in een vat, maar een vat dat de sleutel was.  Klinkt dat logischer? |" },
	{ 366, "Azurewrath en Izual.  Ik weet niet waarom ik dat verhaal niet eerder herinnerde.  Ik heb het vaak genoeg gehoord van mijn grootmoeder en van Cain de verhalenverteller.  Wel, ik hoop dat mijn inlichtingen toch meer hulp dan hinder waren.  Moge het licht u leiden, mijn vriend. |" },
	{ 367, "De ooit trotse Izual zit diep onder het oppervlak van deze wereld gevangen.  Zijn eer is hem ontnomen en zijn gedaante veranderd.  Hij is gevangen in onsterfelijke foltering, belast met het verbergen van juist datgene wat hem zou kunnen bevrijden. |" },
	{ 368, "Farnham is behoorlijk zwaar gaan drinken sinds zijn ontmoetingen in het labyrint.  Maar in het geraaskal van deze dronken man rust een legende die diep doortrokken is van mythe en mysterie. \n \nGa even zitten, mijn vriend, en laat mij u vertellen over Izual en Azurewrath. \n \nDe sage van Izual speelt zich af tijdens de verloren veldslagen in de Hel.  Izual was een engel aan wie een heilige runenkling, Azurewrath, was toevertrouwd. \n \nTijdens een gedurfde aanval op de Helsmidse werd Izual besprongen door honderden geblakerde demonen en dodelijk verwond. \n \nDe duivels wierpen de stervende engel in een duistere kuil waar de machten van chaos hem veranderden terwijl hij verdronk in een draaikolk van brandend bloed. \n \nHet kwaad bezat Izual. \n \nDe veren van zijn vleugels verbrandden en onthulden leerachtige huid, en horens scheurden door het vlees van zijn hoofd. \n \nToen hij eindelijk uit die zwarte kuil oprees, was Izual geen engel meer. \n \nVeranderd in een wezen van kwaad, werd hem opnieuw Azurewrath toevertrouwd, om te verzekeren dat de kling nooit meer tegen de bewoners van de Hel gebruikt zou worden. |" },
	{ 369, "De kling Azurewrath, dat is een legende!  Zij werd gesmeed door de engelachtige wapensmid Cinadide, en gehard in de vuren van het oordeel!  Wie dit wapen hanteert zal de legioenen van de Hel aan zijn voeten vinden!  Als u deze kling hebt gevonden, zou ik werkelijk beginnen te geloven dat u de nachtmerrie die onze stad heeft getroffen kunt be\xebindigen. |" },
	{ 370, "Farnham is vaak verward, maar hij spreekt een machtige naam uit wanneer het woord 'Izual' zijn lippen verlaat. \n \nCain zou u de legende van deze krijger in veel groter detail kunnen vertellen. |" },
	{ 371, "Als je enig spoor van Izual of de kling Azurewrath zou vinden, zou zelfs ik onder de indruk zijn.  Dat is beslist uniek. |" },
	{ 372, "Er is een oud verhaal over een engel genaamd Izual, maar veel meer dan dat herinner ik mij niet. |" },
	{ 373, "Heb je die ooit gehoord die Cain vertelt? \n \nDie vind ik geweldig. |" },
	{ 374, "Waar is die stomme kaart?  Hij hoorde tussen een rots en een boom voor de brug te liggen.  Zou hier moeten zijn... \n \nO, hallo daar.  Had u, eh, niet zien staan. |" },
	{ 375, "Er was een tijd dat deze stad een veelbezochte halte was voor reizigers van heinde en ver.  Er is sindsdien veel veranderd.  Maar verborgen grotten en begraven schatten zijn gangbare fantasie\xebn van elk kind.  Wirt geeft zich zelden over aan jeugdige spelletjes.  Dus het kan gewoon zijn verbeelding zijn.|" },
	{ 376, "Rots?  Boom?  Brug? \n \nIk heb geen idee waar u het over hebt. |" },
	{ 377, "Zet uw zoektocht voort.  Een schat vinden die verloren is, is niet gemakkelijk.  Een schat vinden die verborgen is, nog minder.  Ik laat u dit mee.  Laat het zand des tijds uw zoektocht niet verwarren.|" },
	{ 378, "Een wat?!  Dit is dwaasheid.  Er ligt hier in Tristram geen schat begraven.  Laat eens zien!  Ah, kijk, deze tekeningen kloppen niet.  Ze komen helemaal niet overeen met onze stad.  Ik zou mijn gedachten houden bij wat onder de kathedraal ligt en niet bij wat onder onze bovengrond ligt.|" },
	{ 379, "Ik wed dat Wirt je aan zag komen en een toneelstukje opvoerde zodat hij je later kon uitlachen terwijl je met je neus in het zand door de stad rende.  Ik zou het negeren.|" },
	{ 380, "H\xe9, laat 's zien. \n \n*Snuit zijn neus* \n \nBedankt! |" },
	{ 381, "H\xe9 jij daar!  Kom 's hier, luister!  Weet je van het eiland waar engelen waken?  Kies de juiste stenen, maar je kan je ogen maar beter afschermen, alles afschermen!  Ik weet 't, want ik ben er geweest en...  mmm, bier. |" },
	{ 382, "Weet u, soms vraag ik mij af hoeveel vertrouwen je kunt stellen in wat Farnham zegt.  Hij brengt zoveel tijd door met het herbeleven van zijn herinneringen aan het labyrint en met simpelweg dronken zijn dat hij niet altijd veel zinnigs zegt.  U zou het echter kunnen navragen. |" },
	{ 383, "Dat zijn de woorden van een dronkaard. \n \nIk zie niet in hoe ze waar zouden kunnen zijn. |" },
	{ 384, "Dit is \xe9\xe9n keer dat u naar Farnham zou moeten luisteren.  Ik heb van deze plaats gehoord, en ik ken enkele tovenaars die hebben geprobeerd een portaal te scheppen om er te komen. |" },
	{ 385, "Deze legendarische plaats bestaat echt.  En grote beloningen wachten u mocht u haar vinden.  Meer kan ik niet zeggen. |" },
	{ 386, "Voor \xe9\xe9n keer kan ik instaan voor Farnhams buitengewone bewering. \n \n \nEr wordt in de boeken die ik heb gelezen veelvuldig melding gemaakt van een plaats van grote genezing waar krijgers van het licht heen gingen om de wonden te helen die zij in de Zondeoorlog hadden opgelopen. \n \n \nAls u deze plaats zou kunnen vinden, zou dat vrijwel zeker ons allen ten goede komen. |" },
	{ 387, "Hmm, een eiland waar engelen waakten?  Hoewel Farnhams geheugen tegenwoordig vaak troebel is, komt dat inderdaad bekend voor.  Wellicht kunnen de oude kronieken van de Zondeoorlog ons helpen. \n \nAh, ja, hier is iets.  In een lang vergeten tijd rustte een blauwe zee aan de rand van een vurige onderwereld.  Dit was een oase voor hen die als wachters over de poorten van de hel dienden.  Engelen en krijgers van het licht konden deze plaats gebruiken om zichzelf te genezen en hun krachten te verzamelen.  Het was ook een verzamelplaats waar zij konden oefenen en zich op de Zondeoorlog konden voorbereiden.  Legenden spreken van een drietal rotsen die het pad naar dit eiland van de zonloze zee verbergen. |" },
	{ 388, "Farnham spreekt van een plaats die bestaat, ten minste in de legende.  Krijgers gingen naar een plaats aan de rand van de hel om zich te wapenen voor de strijd tegen de legers der duisternis.  Als de verhalen waar zijn, zouden er onmetelijke schatten op dit eiland van de zonloze zee kunnen liggen. |" },
	{ 389, "Ik heb een zeer verontrustende ervaring gehad die ik met u moet delen, mijn vriend. \nEerder vandaag werd ik geroepen om een van de mannen te helpen die uit het Labyrint waren ontsnapt.  Hij was gestoord, gewelddadig en bleef uithalen naar allen die hem probeerden te kalmeren.  Ik vermoedde dat hij bezeten was door een of andere demonische entiteit en begon dus het kwaad uit hem te drijven.  \n \nNa vele uren wist ik een demon uit te drijven die zich \\\"Fleshdoom\\\" noemde, maar het helgebroed vluchtte het Labyrint in. \nU denkt wellicht dat ik gek ben, maar na met de man te hebben gesproken en met Fleshdoom te hebben gestreden, geloof ik dat het Labyrint op de een of andere manier een poort naar de onderwereld is geworden.  Naarmate u dieper afdaalt, kunt u zich op de drempel van de Hel zelf bevinden.\nTen slotte behield de man die bezeten was herinneringen aan een oude demonenkling genaamd \\\"Shadowfang\\\".  Als u de demon Fleshdoom vindt, hoed u dan voor dit vuile zwaard.  Ik vrees intussen dat de gevaren beneden nog groter worden.\nU MOET Fleshdoom vinden en hem doden.  Breng het zwaard naar mij en ik kan het vernietigen, maar HANTEER HET NIET!  Want zijn macht kan volstrekt bederven! |" },
	{ 390, "Al wat ik nu kan doen is voor ons allen bidden... |" },
	{ 391, "Fleshdooms ondergang is een groot goed voor de wereld, en toch bestaat Shadowfang nog!  Het moet gevonden en vernietigd worden!  Probeer de demonenkling niet te gebruiken, kampioen.  Zij zal elke sterveling die haar hanteert bederven en krankzinnig maken.  Ik alleen kan haar duistere kwaad be\xebindigen. |" },
	{ 392, "Waarom talmt u?  Tijd is van het grootste belang!  De prins en het volk van dit koninkrijk rekenen op u. |" },
	{ 393, "Het Licht zij geprezen!  U hebt de vervloekte demonenkling gevonden.  Alleen haar vernietiging kan de veiligheid van ons allen verzekeren.  Wacht, wat is dit voor verraad?  Au!  Het brandt!  Helvuur...  het verteert mij!  U moet dit naar de Helsmidse brengen en het erin werpen voordat...  Neeeee! |" },
	{ 394, "Ik hoorde dat de priester Tremain een uitdrijving zou verrichten, maar ik ben niet gegaan.  Ik zie niet in waarom wij allen elk ogenblik gevangen moeten zijn in wat er onder onze stad loert.  Ik weet dat velen door de handen van deze monsters zijn gestorven, maar wij moeten proberen verder te gaan.  Ik weet dat u hier bent gekomen om Tristram uit de klauwen van de duisternis te bevrijden, en ik hoop dat wij op een dag weer in vrede kunnen leven. |" },
	{ 395, "Ah, u spreekt van een oud en boosaardig wapen.  Treed behoedzaam op dit terrein, want de legenden van Shadowfang zijn zo zwart als een maanloze winternacht.  Gesmeed in de Helsmidse kan Shadowfang de ziel zelf uit wie zij treft rukken.  Ik benijd u niet als u van plan bent hem te verslaan die haar hanteert.  Moge het licht u beschermen, dappere held. |" },
	{ 396, "Je gaat op een demon jagen, is dat wat je zei?  Ik weet dat ik dat niet gehoord heb, want niemand jaagt op demonen!  Nee!  Niemand! |" },
	{ 397, "Mij werd gevraagd bij de uitdrijving te assisteren.  Mijn vaardigheden konden het lijden van de arme man verlichten terwijl Tremain de demon uit zijn lichaam dreef.  Terwijl ik hem behandelde voor een uitzonderlijk hoge koorts, sprak hij van een plaats van verzengende hitte.  De gefolterde man riep uit over de Hel en over het vallen in een kuil van vlammen.  Ik kon er geen wijs uit worden, en gelukkig herstelde hij spoedig. |" },
	{ 398, "Ik weet niet wie die Fleshdoom is, maar ik heb geruchten gehoord over een ebbenhouten kling die een ziel van het lichaam klieft.  Zelfs ik zou dat ding niet proberen te verkopen, ongeacht de winst.  Als je het vindt, zou je moeten doen wat Tremain zegt en het zo snel mogelijk vernietigen. |" },
	{ 399, "De priester Tremain is een heilig man van een oude orde.  Hun omgang met de kwade krachten die aan het werk zijn wordt zeer gerespecteerd en is goed gedocumenteerd.  Ook ik heb legenden gehoord die spreken van een vervloekte demonenkling genaamd Shadowfang.  Men zegt dat zij de gefolterde zielen van haar slachtoffers verslindt.  Deze zielen zitten gevangen in haar ebbenhouten kling en versterken haar onheilige macht.  Ik heb ook gelezen over een grote Helsmidse waar zelfs het machtigste wapen geschapen of vernietigd kon worden.  Treed behoedzaam op wanneer u met Shadowfang en haar meester te maken hebt, opdat u niet ook in het zwaard wordt getrokken. |" },
	{ 400, "Ik zag de uitdrijving.  Het was ongelooflijk hoe Tremain de boze geest uit dat gepijnigde en gefolterde lichaam dreef.  Ik bid dat zoiets afschuwelijks hier nooit meer iemand overkomt. |" },
	{ 401, "U moet immer waakzaam zijn, want Fleshdoom is een vijand die zowel wreed als snel is.  Zijn ebbenhouten kling is samengesteld uit de essentie van het kwaad.  Als u hen beiden kunt vernietigen, zou dat veel doen om zijn duistere meester te verzwakken. |" },
	{ 402, "Hoewel ik begrijp dat uw doel van een hogere roeping kan zijn, is welverdiend goud vast welkom.  Enkele dorpelingen uit een nabijgelegen dorp hebben een beloning geboden voor de vernietiging van een wezen dat hun huizen en bezittingen met de grond gelijkmaakte.  Zij eisen onomstotelijk bewijs dat het wezen gedood is, en ik kan mij daarvoor slechts \xe9\xe9n manier bedenken. |" },
	{ 403, "Je kunt zeggen wat je wilt, maar zonder bewijs kan ik je de beloning niet geven. |" },
	{ 404, "Bah, walgelijk!  Maar zeker bewijs genoeg voor iedereen.  Hier is je beloning, zoals beloofd. |" },
	{ 408, "Goede meester, een ogenblik van uw tijd alstublieft.  In mijn herberg is 's nachts ingebroken.  Niemand raakte gewond, maar er zijn veel voorwerpen gestolen, waaronder een kist die toebehoorde aan een geheimzinnige zwerver die hier ooit verbleef.  Ik vond het lichaam van een dief nabij de kathedraal, met veelzeggende wonden van een van de wezens beneden op zijn gebroken lichaam.  Sommige gestolen waren lagen bij het lichaam, maar de kist, en de sleutel om hem te openen, waren nergens te bekennen.  Mocht u die sleutels tijdens uw dappere kruistocht vinden, neem ze dan mee, en als u dan de kist vindt, kunt u hem openen en zien welke geheimen hij bevat.  Wellicht is het iets dat u bij uw opdrachten kan helpen. |" },
	{ 409, "Onthoud goed, goede meester: de kist zit op slot en is nutteloos zonder de sleutel.  Als u de kist wel vindt en de sleutel hebt, moet u kijken wat erin zit.  Ik...  verwacht de eigenaar hier niet meer terug. |" },
	{ 410, "Ik zie dat u de sleutel hebt gevonden.  Nu hoeft u alleen nog de kist te vinden waar hij bij hoort. |" },
	{ 411, "Uw dappere verhalen over het bevechten van demonen hebben mij aan iets herinnerd, goede meester.  Er trok hier enige tijd geleden een reiziger doorheen.  Hij was bijzonder trots op een zeer uniek wapen dat hij droeg, en terwijl hij behoorlijk dronken werd, pochte hij over zijn macht.  Ik heb hem nooit teruggezien, en ik vermoed dat hij zich te dicht bij de kathedraal waagde. |" },
	{ 412, "Hebt u die reiziger ooit gezien waarover ik u vertelde?  Die met het betoverde wapen?  Wel, ik neem aan dat hij ons dorp heeft verlaten zoals zovelen, of hij moet dood zijn. |" },
	{ 413, "Ja, dat is beslist het wapen dat hij droeg.  Weet u, ik heb nagedacht over iets anders dat die reiziger zei.  Hij gaf te kennen dat de ware machten van het wapen pas ontketend zouden worden wanneer het het bloed van een zeer bepaald soort wezen proefde. |" },
	{ 414, "Waren de verhalen die de reiziger vertelde waar?  O, ik zie dat u het nog niet weet.  Wel, ik herinner mij duidelijk dat hij zei dat het wapen dat u vond iets heel bijzonders zou worden door een bepaald monster te doden. |" },
	{ 415, "Mijn vriend, ik moet u spreken.  Terwijl ik op weg was om een zieke dorpeling te helpen, stuitte ik in de stad op een demon.  Ik vluchtte het huis uit...  en liet in mijn haast per ongeluk de deur openstaan.  Ik bid dat het vuile wezen er nog is.  Alstublieft, help ons, voordat het ons allen komt halen!| " },
	{ 416, "Deze wezens moeten uit onze stad verbannen worden.  Tot mijn schande liet ik de deur openstaan, maar daardoor zult u het huis des te gemakkelijker vinden. |" },
	{ 417, "Opnieuw staat de stad bij u in het krijt.  Het is enkel uw kracht en wilskracht die ons uit deze kwade tijd kan leiden. |" },
	{ 418, "Mijn grootmoeder droomde vannacht over u!  Zij zei dat u in haar droom met uw blote handen een van die vuile monsters versloeg die onder de kerk loeren.  Toen het stierf, spatte het uiteen in een fabelachtige schat.  Hoewel zij een beetje bang was van haar droom, kon zij het beest mij vrij duidelijk beschrijven...|" },
	{ 419, "Mijn grootmoeder had precies dezelfde droom opnieuw!  Zij zei dat u zeer dapper was en erg tevreden leek met uw prijs. |" },
	{ 420, "Houd je ogen open voor een beeldje van ijzer.  Ik heb enkele oude verslagen ontdekt over een bepaald type beeldje, en de geheimen van metaalbewerking die het bevat.  Als je ziet wat ik zoek, pak het dan en breng het meteen naar mij. |" },
	{ 421, "O, de geheimen van dit metaal zijn fantastisch! \n \nO, hoe zou ik het juiste voorwerp van macht kunnen laten glanzen... \n \nIk zou iets kunnen maken dat de krijgers van de hemel waardig is! |" },
	{ 422, "Je inspanningen zijn niet tevergeefs.  Het lijkt erop dat alles is zoals ik had gehoopt. \n \nIk vertrouw erop dat je dit nuttig zult vinden in je gevechten beneden. |" },
	{ 423, "Opnieuw heb ik uw sterke arm en scherpe verstand nodig om de mensen van deze stad te helpen.  Ik heb bepaalde reagentia nodig om de plagen te bestrijden die de demonen door hun loutere aanwezigheid over het land hebben ontketend.  Als u deze paar dingen zou kunnen verzamelen, zal het vele levens redden.| " },
	{ 424, "De ziekten verspreiden zich snel, en velen sterven.  Alstublieft, help mij door de reagentia te vinden, zodat ik er een tegengif van kan maken. |" },
	{ 425, "Heel hartelijk dank!  U brengt hoop en licht in deze duistere en moeilijke tijden. \n \nIk wil dat u dit hebt, in de hoop dat het u zal helpen in uw strijd tegen de duisternis. |" },
	{ 426, "Ik heb geluk!  Een karavaan is net buiten het dorp gestopt en brengt voorraden naar de landen van het oosten.  Bepaalde voorwerpen brengen een bijzondere prijs op, als je ze voor mij kunt krijgen. |" },
	{ 427, "We kunnen er allebei een mooie winst op maken als je mij de juiste waren kunt bezorgen.  Wat zeg je ervan? |" },
	{ 428, "Ah, je bent net op tijd.  De karavaan vertrekt vanavond.  Hier is jouw deel, vriend. |" },
	{ 429, "Kijk, ik weet dat mijn prijzen hoog zijn, maar...  een van mijn contacten had een...  ongeluk.\n \n \nEn ik heb hulp nodig om mijn meer alledaagse voorraad aan te vullen. \n \n \nIk ruil je een kwaliteitsvoorwerp, als je dit kleine lijstje even voor mij kunt afwerken. |" },
	{ 430, "Luister, ik zal het je tijd waard maken als je mij haalt waar ik om vroeg.  Trouwens, je wilt vast weten wat ik je in ruil ga geven... |" },
	{ 431, "Bedankt.  Hiermee red ik het tot ik een nieuw loopjongen vind.  Jammer dat je het zo druk hebt.  O ja, hier is jouw deel van de afspraak. |" },
	{ 432, "H\xe9 jij!  Ja, ik heb het tegen jou!  Ik...  ben aan dit vreemde boek gekomen.  Ik weet dat het iets groots moet doen, maar je hebt een kristallen oculair nodig om het te lezen, dus voor mij is het waardeloos.  Ik zou je deze zeldzame en mystieke foliant echter wel willen ruilen, voor slechts een paar dingen. |" },
	{ 433, "Kijk, dit heel bijzondere boek dat ik heb kan van jou zijn voor zo weinig.  Vertel niemand wat een geweldige deal ik je geef, want dat zou mijn reputatie ru\xefneren... |" },
	{ 434, "Verbazingwekkend!  Je hebt werkelijk alles gevonden wat ik wilde.  Wel, hier is het boek, maar je zult een kristallen oculair moeten vinden om het te lezen.  Veel geluk! |" },
	{ 435, "Mijn grootmoeder vertelt mij vaak verhalen over de vreemde krachten die het kerkhof buiten de kerk bewonen, en het kan u wel interesseren er een van te horen.  Zij zei dat als u de juiste offergave op het kerkhof zou achterlaten, de kathedraal zou binnengaan om voor de doden te bidden, en dan zou terugkeren, de offergave op een vreemde wijze veranderd zou zijn.  Ik weet niet of dit slechts het gepraat van een oude, zieke vrouw is, maar tegenwoordig lijkt alles mogelijk.|" },
	{ 436, "Ik weet dat het verhaal van mijn grootmoeder vreemd lijkt, maar rond het kerkhof hangen vele mysteries.  \n \nHet kan toch geen kwaad daar iets neer te leggen en te zien wat er gebeurt?  \n \nMisschien ontdekt u iets dat ons allen zal helpen.|" },
	{ 437, "Ik geloof dat ik een manier heb gevonden om sommige wapens sterk te verbeteren.  Als je mij kunt brengen wat ik nodig heb, wil ik mijn idee wel uitproberen, en als het werkt, is het van jou.|" },
	{ 438, "Ah, ik denk nog steeds dat ik het juiste wapen kan verbeteren.|" },
	{ 439, "Even dit doen...  en dit...  en dit.  Ah!  Het werkt.  Neem dit terug en probeer het uit.|" },
	{ 440, "Ik weet dat ik veel van u vraag, maar ik moet u nu vragen een poel met helder water te vinden.\n \nNeem deze vaten.  Vul ze en breng ze zo snel mogelijk bij mij terug. \n \nMet het heldere water kan ik een elixer van wonderbaarlijke kracht maken dat ons allen ten goede zal komen.|" },
	{ 441, "Hebt u wat ik nodig heb?  Het heldere water stelt mij in staat een zeer krachtig elixer te maken.  Vul de vaten die ik u gaf en kom ermee terug.|" },
	{ 442, "Zeer goed, mijn vriend!  Zeer goed! \n \nGeef mij een minuut om deze ingredi\xebnten te mengen...  volmaakt! \n \nHier is wat van het elixer, zoals beloofd.|" },
	{ 443, "Uw dappere verhalen over het bevechten van demonen hebben mij aan iets herinnerd, goede meester.\n \nEr trok hier enige tijd geleden een reiziger doorheen. \n \nHij was bijzonder trots op een zeer uniek wapen dat hij droeg, en terwijl hij behoorlijk dronken werd, pochte hij over zijn macht. \n \nIk heb hem nooit teruggezien, en ik vermoed dat hij zich te dicht bij de kathedraal waagde.|" },
	{ 444, "Hebt u die reiziger ooit gezien waarover ik u vertelde?  Die met het betoverde wapen?  Wel, ik neem aan dat hij ons dorp heeft verlaten zoals zovelen, of hij moet dood zijn.|" },
	{ 445, "Ja, dat is beslist het wapen dat hij droeg. \n \nWeet u, ik heb nagedacht over iets anders dat die reiziger zei.  Hij gaf te kennen dat de ware machten van het wapen pas ontketend zouden worden wanneer het het bloed van een zeer bepaald soort wezen proefde.|" },
	{ 446, "Het lijkt erop dat er vele toepassingen zijn voor de rollen die onder de kerk gevonden worden. \n \nIk zou een boek van magie kunnen schrijven als ik genoeg van de juiste rollen had om te bestuderen.|" },
	{ 447, "Onthoud: met genoeg rollen kan ik een boek van magie voor u maken.|" },
	{ 448, "Ja, ik kan zien dat wanneer ik deze rollen zo combineer... \n \nIk zal u leren wat ik heb geleerd, zodat ook u meer geheimen van deze magie kunt kennen.|" },
	{ 449, "Je bent uitverkoren om een van mijn dienaren te worden.\n \nDien mij goed en ik zal je machten en rijkdom geven die je stoutste dromen te boven gaan.\n \nStel mij teleur en je beloning zal eindeloos lijden zijn.\n \nJe eerste taak is te verhinderen dat de watervoorziening van Tristram wordt gezuiverd.  Ga daarheen en ruim de lastige helden op.|" },
	{ 450, "Ik heb nog een missie voor je.\n \nDoor de Watervoorziening vervuild te houden bleven de helden met lege handen achter, en zij lanceerden een verrassingsaanval op de Stille Bronnen op zoek naar zuiver water.\n \nJe gaat onmiddellijk naar de Stille Bronnen en zorgt dat zij daar de dood vinden in plaats van water.|" },
	{ 451, "Het water ligt achter ons.  Wat nu komt is erger en gevaarlijker.\n \nEen van hun schrijvers is aan het schrijven geweest.  Elke put, elk lijk, elk gefluister - hij naait ze aaneen tot \xe9\xe9n bladzijde, en die bladzijde eindigt met mijn naam en de weg naar mijn deur.\n \nGa naar het Lagere Scriptorium en ruim die schrijver op.  Het portaal is open.  Wees snel.|" },
	{ 452, "Goed gedaan met de schrijver.  Dat koopt ons tijd.\n \nIntussen heeft mij bericht van een verrader bereikt.\n \nEr is een lastpost die bekendstaat als Az'dog.  Een naam even dom als zijn drager.  Een van de onderdemonen.  Gevallen.  Hij en zijn metgezellen hebben gefluister naar mensen gebracht.\n \nDit zal niet geduld worden.  Ik wil dat gedrocht zo dood als een held die van zijn harnas is ontdaan in een kuil met uitgehongerde lijkenvreters.\n \nHet portaal is open.  Ga en geef het wezen zijn 'Beloning'.|" },
	{ 453, "De verrader is dood, maar de schade is aangericht.  Hij had al gepraat, en zij handelen er al naar.  Ik heb de vasthoudendheid van deze helden onderschat.\n \nHet doet er niet toe.  Het zal slechts een lichte vertraging blijken.\n \nVier van hun kapiteins hebben een raad bijeengeroepen op een plaats die zij geheim wanen, en beramen hun volgende zet.\n \nJij gaat hen een bezoek brengen.  Maar wees gewaarschuwd: dit zijn niet de stakkers die je hebt afgeslacht.  Zij zijn sterker, beter gepantserd en ervaren in de strijd.  Bereid je deze keer goed voor.|" },
	{ 454, "Zij graven weer.  Zoekend naar een tombe, een dode ridder, het harnas waarin hij wegrotte - zij zoeken het heilige harnas dat Arkaines Moed heet.  De dwazen geloven dat het een soort oud reliek is dat het tij van de Zondeoorlog zal keren.  Het is slechts staal op een lijk.  Niets bijzonders.\n \nMaar sleep het het daglicht in en elke boer met een hooivork herinnert zich weer hoe je hoopt.\n \nGa de gravers doden.  Dood degene die kwam om het te dragen.  Laat hen in de deuropening liggen waar de volgende expeditie hen zal vinden.  Neem daarna het harnas, als het je vermaakt.  Zo niet, gooi het weg.  Het kan mij niet schelen.|" },
	{ 455, "Je bent precies op tijd.\n \nGisteren stuitte een groep Opperheren tijdens een patrouille op een grote afdeling gewapende heldenstrijdkrachten in de streek die bekendstaat als de Riolen.  Zij vochten dapper tegen deze overweldigende macht, maar zij werden vernietigd.\n \nIk stuurde een groep van 50 in de strijd geharde Kuildemonen om dit af te handelen en zij zijn nu in hevig gevecht met de helden.  Hoewel zij de helden met succes naar de noordelijke streek van de Riolen hebben gedreven, zijn hun verliezen verbijsterend.  Deze slag is verloren.\n \nJouw missie is te gaan en het werk af te maken dat zij begonnen zijn.  Elimineer alle overgebleven heldenstrijdkrachten, maar verwacht zware weerstand.  Zij zijn een in het nauw gedreven ridderafdeling, zonder terugtocht, en zij zullen zeker tot de dood vechten.  Jij zorgt dat zij inderdaad tot de dood vechten.|" },
	{ 456, "Je hebt deze ridders zonder genade en zonder aarzeling afgehandeld.  Nu is het tijd om je vermogens te beproeven.\n \nIk heb berichten over een grote samenkomst van helden in de Oude Crypten.  Dat is dicht genoeg bij mijn locatie.  Ik zal hun aanwezigheid in deze streek niet dulden - en het is een gelegen kans om hun toekomstige activiteit hier te verlammen.\n \nJouw doel is zoveel mogelijk helden te elimineren.  Wis elk spoor van hen van deze plaats.  Zij behoort aan demonen, niet aan mensen.|" },
	{ 457, "Het Duistere Nest loopt dieper dan het broedsel nodig heeft.\n \nZijn laagste tunnels komen uit in de Crypte.  De helden die haar bereikten weten dat nu.\n \nZij zijn daarboven en leren de afdaling goed genoeg om haar te onderwijzen.\n \nJe gaat een gevecht in zoals je er nog geen hebt meegemaakt.  Zij kwamen door het broedsel en bleven leven, en hun geloof, hoe misleid ook, geeft hun kracht.\n \nDood hen allen.  Laat niemand over om de kaart te tekenen.|" },
	{ 458, "Zij zijn teruggegaan naar de watervoorziening.  Opnieuw.  En zij hebben hun besten gestuurd.\n \nGa terug en neem het hun opnieuw af.  Laat hun niets.  Niet het water, niet de mannen, niet het idee dat het ooit de moeite waard was het te proberen.  Laat hen hun eigen bloed drinken.\n \nDeze twee zullen je bij de missie helpen.|" },
	{ 459, "Goed gedaan met die helden in de Watervoorziening.  Zij zullen zich wel twee keer bedenken voordat zij deze plaats opnieuw aanvallen.\n \nMaar ik heb nog een belangrijke zaak af te handelen.  Hephasto, een van de bekwaamste wapensmeden van de Hel, wil het legendarische voorwerp dat het Aambeeld van Woede heet.  Hij gelooft dat dit aambeeld hem in staat zal stellen wapens en harnassen van betere kwaliteit te smeden, wat demonen op hun beurt een voordeel in de strijd zal geven.  Ik ben voornemens zijn zaak te steunen.\n \nEn jij zult degene zijn die dat aambeeld voor hem gaat halen.\n \nBericht dat ook de helden ernaar zoeken heeft mij eveneens bereikt.  Je zult hen dus moeten opruimen als zij opduiken waar jij heen gaat.\n \nEn je gaat naar een streek die bekendstaat als de Diepere Grotten.  Breng mij het Aambeeld.  En dan zullen wij die dwazen van boven laten zien dat er geen dodelijker wapens zijn dan die in de Hel gemaakt zijn.|" },
	{ 460, "uitstekend.  het aambeeld zal zijn deel doen.\n \nnu naar andere zaken.\n \nik hoorde dat de helden een nieuwe generaal hebben die belooft het kwaad in de diepte van het labyrint te verpletteren.  zijn afdeling daalt af naar de crypten.  je moet hen onderscheppen op de plaats die bekendstaat als Pandemonium.|" },
	{ 461, "Een van mijn hooggeplaatste dienaren heeft zich in de nesten gewerkt.\n \nAartsbisschop Lazarus.  Zijn schuilplaats bovenin Tristrams Kathedraal wordt aangevallen door elite-heldenstrijdkrachten.\n \nIk zal de meisjes vooruitsturen om goede Lazarus te helpen, maar ik stuur jou er ook heen om het zeker te weten.\n \nDe missie is Lazarus niet te laten sterven.\n \nMocht je falen en Lazarus laten sterven, dan zul je snel zijn pad volgen.|" },
	{ 462, "Wat doe jij hier?  Hoe ben je hier gekomen?  Wie heeft je gestuurd?\n \nMeester?  Geprezen zij mijn heer!\n \nUw timing was onberispelijk.  Neem dit als blijk van mijn waardering.\n \nMaar laat mij nu alleen.  Ik moet rusten.|" },
	{ 463, "Er verbergen zich drie arrogante Tovenaars in de Bloedburcht met hun schatten.  Ik wil hen dood.  En ik wil dat hun goud naar mij wordt gebracht.  Mijn demonenleger zal er beter gebruik van maken.\n \nEn jij krijgt ook jouw deel.  Je zult niet teleurgesteld worden.|" },
	{ 464, "De Helsmidse wordt aangevallen.  Hephasto heeft bescherming nodig.  Dus doe wat beschermwerk.\n \nEn een advies.  Bereid je goed voor.  Men zegt mij dat zij daar heel wat gepantserde ridders heen hebben gestuurd.  Dat soort is gevaarlijker.|" },
	{ 465, "Goed gedaan.  Dat zou hun een lesje moeten leren over het aanvallen van de Helsmidse.\n \nWat jou betreft: neem dit wapen.  Het is nieuw gesmeed met het Aambeeld van Woede.\n \nMoge het je goed van dienst zijn tegen de horde oppervlaktebewoners.|" },
	{ 466, "Je volgende missie is te reizen naar het ondergrondse labyrint dat de Stinkende Grot heet.\n \nIk weet niet waarom zij troepen naar dat gebied hebben gestuurd en ik wil het niet weten.  Ik wil ze alleen allemaal dood.\n \nHet portaal is open.  Begin.|" },
	{ 467, "Mijn leger drijft de helden terug naar het oppervlak.  Zij zijn nu de Hel uit.  De contactlijn is verschoven naar de Grotten.\n \nEn jouw volgende opdracht is de Mijngrotten.  Daar is een elite-boogschuttersafdeling gesignaleerd.  Jouw doel is haar te elimineren.  Ik laat er een demonenafdeling achteraan sturen om te verzamelen wat er van hen over is.|" },
	{ 468, "Het lijkt erop dat wij opnieuw een tegenslag hebben geleden en dat helden de Helpoort bestormen.\n \nHoewel het, daar ben ik zeker van, de laatste tegenslag is, moet jij naar de Helpoort reizen en een einde maken aan die afdeling van menselijk verzet.\n \nMaak er haast mee.  Wij moeten omhoog blijven trekken.  Wij staan op het punt in de Catacomben door te breken.  De laatste fase is nabij.|" },
	{ 469, "De Helpoort is nu onder controle.  Eindelijk.\n \nNu over je volgende missie.  Mijn verkenners hebben een van de vluchtende heldengroepen gevolgd naar de bovenste Grotniveaus.  Zij meldden dat helden de gebruikelijke route omlaag vanuit de Catacomben gebruiken, maar er is er nog een.  Een oud gebied.  Zij noemen het Necropolis.  Zoals vermoed ontdekten zij waarom helden dit pad naar de Grotten niet gebruiken: het is zwaar vergeven van Ondoden.  Het weinige dat over deze plaats bekend is, suggereert dat zij een geheime begraafplaats was voor leden van de Horadrim, de geheimzinnige magi\xebrsorde die mijzelf en mijn broers lang geleden gevangen zette.\n \nIk wil dat hun resten vernietigd en tot stof gemaakt worden.  Zelfs in de dood mogen zij geen redding vinden voor mijn wraak.  Dit is je hoofddoel voor die missie: vernietig alle Horadrim-leden die uit hun graven zijn opgestaan.\n \nJe tweede doel is heel Necropolis te zuiveren en het daarmee tot een veilige doorgang voor mijn leger te maken.  Dat zou ons een voordeel moeten geven om sneller het oppervlak te bereiken.|" },
	{ 470, "De tijd om de strijd naar menselijk gebied te brengen is nu.\n \nNu Necropolis een veilige doorgang voor mijn leger is, kunnen wij het menselijk verzet in de Catacomben treffen.  Dit is hun gebied.  Gebouwd door mensen.  Maar niet voor lang.  Spoedig zal het aan demonen toebehoren.\n \nHet gebied boven Necropolis dient als kazerne voor hun contingent.  Het staat bekend als de Galg.  En daar slaan wij nu toe.  Tref je voorbereidingen en vertrek onmiddellijk.\n \nIngerukt.|" },
	{ 471, "Een van de verkenners keerde vandaag terug met de melding dat een grote afdeling vuurtovenaars op weg is naar de grotten via de streek van de Grafkelder.  Je moet daar onmiddellijk heen vertrekken.  Jouw doel is deze afdeling te onderscheppen en te elimineren.\n \nJe tweede doel is zoveel mogelijk heldenstrijdkrachten in dat gebied te doden.\n \nEr is geen tijd te verliezen.  Ga.  Nu.|" },
	{ 472, "Soldaat.\n \nElke dag brengt ons dichter bij de eindconfrontatie met de oppervlaktebewoners.  Mijn leger heeft nieuwe tactieken geleerd, zijn arsenaal vergroot en zijn machtsgebied versterkt.  Maar de mensen zijn nog te talrijk en te machtig.  In de onderwereld zeggen wij dat het doden van een slang onthoofding vergt.  Maar in deze situatie moeten wij haar eerst verzwakken.  Begin bij de staart en werk naar de kop toe.\n \nMijn leger heeft de laagste niveaus van de Kathedraal bereikt.  Die zijn rechtstreeks met het oppervlak verbonden.  Dit is de laatste stoot.  En dit is wat de helden fel zullen verdedigen.\n \nJe moet naar het district van de Vervallen Tempel reizen en ervoor zorgen dat het van de menselijke dreiging gezuiverd wordt.  Demonen zullen dit geheime kelderniveau gebruiken om ongemerkt de Kathedraal binnen te stromen.\n \nWij treden de laatste fase van mijn plan binnen.  Maar denk niet dat het voorbij is zodra wij het oppervlak veroverd hebben.  Er zijn grotere plannen die daar ver voorbij reiken.  Maar die zal ik later onthullen.\n \nBovenal: voltooi je missie, maar houd je ogen open voor bijkomende inlichtingen of zwakte die zich zou kunnen voordoen.\n \nHet portaal is open.  Begin.|" },
	{ 473, "Terwijl mijn troepen helden bevechten op de lagere Kathedraalniveaus, moet jij naar de kerker reizen waar de helden hun voorraden opslaan en die infiltreren.  Neem alles van waarde.  En hoed je voor de helden - deze plaats moet zwaar bewaakt zijn.\n \nJe hebt je bevelen.  Het portaal is geregeld.  Ga.  En stel mij niet teleur.|" },
	{ 474, "De volgende missie is...  ik vind haar vermakelijk.  Er is een afdeling elitekrijgers die de helden hebben gestuurd om hen te helpen die in de Kathedraal demonen bevechten.  Maar zij zijn verdwaald in het Spookachtige Labyrint.  Het is een gelegen kans voor ons om deze kretins hun weg te helpen vinden.  Ga daar nu meteen heen en help hen.  Ik neem aan dat je weet wat voor soort hulp ik bedoel...|" },
	{ 475, "De overwinning is nabij.  Mijn leger drijft de helden terug naar het oppervlak, wij zijn er bijna.  En wij zijn bijna klaar.\n \nEen van de elite-heldenafdelingen heeft een van mijn trouwe dienaren weten te vangen: de Slachter.  Ik wil dat je naar de kelder van de Kerksacristie reist waar zij hem vasthouden, en hem bevrijdt.  Hij zal je vergezellen in de laatste strijd die komen gaat.|" },
	{ 476, "Ahh, vers vlees!\n \nHet is een grap, maak je geen zorgen.  Ik praat niet ruw tegen mijn eigen soort.  Zo begroet ik gewoonlijk helden.  Ze kijken altijd bang en beginnen te rennen, met een nat spoor achter zich.  Verdorie, het wordt tijd dat ze mij daarom pisloper gaan noemen.\n \nHoe dan ook, je hebt er lang genoeg over gedaan om hier te komen.\n \nDit gaan we doen.  De bevelen van de meester zijn dat ik mij bij je voeg en je help wat helden te hakken en te snijden.  Dat is wat wij gaan doen.\n \nDaarna stuurt de meester je naar het oppervlak.  Waar wij dit menselijk verzet eens en voor altijd be\xebindigen.\n \nWel, ga voor.|" },
	{ 477, "Dit is het.  Onze laatste slag met deze stad.  Terwijl jij weg was op je missies heeft mijn leger het dorp hierboven vernietigd en platgebrand, en iedereen gedood.  Wij zijn zegevierend.  De menselijke dreiging is uitgeroeid.  Hun elitekrijgers zijn gevlucht naar het nabijgelegen dorp Ravenholm.  Mijn verkenners meldden dat de Smid van het dorp uit zijn graf is opgestaan en een horde zombies naar die plaats leidt.  Erbarmelijker dan dat kan het onmogelijk worden.\n \nRuim deze kretins op en breng verslag uit.  Wees snel.  Ik heb grotere zorgen waaraan ik aandacht moet besteden.|" },
	{ 478, "Goed gedaan.\n \nHet is een groots slot voor deze stad.\n \nIk zal enkele van mijn dienaren deze plaats laten herinrichten en versterken; zij zullen haar als basis gebruiken om meer demonen deze wereld in te storten.\n \nWat jou betreft: jouw rol moet nog gespeeld worden.\n \nEnige tijd geleden trachtte ik de geest te bezitten van Koning Leoric, die eens over dit land heerste.  Maar na al die jaren van gevangenschap onder deze vervloekte Kathedraal was ik niet sterk genoeg.  De koning verloor zijn verstand.  En goede Lazarus stelde voor dat ik hetzelfde met zijn jongere zoon Albrecht zou proberen.  Dat plan slaagde.  En sindsdien gebruik ik Albrechts lichaam als vat.  Maar ik heb een nieuw nodig.  Een sterker lichaam.\n \nIk heb je vorderingen met belangstelling gevolgd en besloten dat jij mij hierbij zult helpen.  Ik vraag het niet, het is besloten.  Het ritueel begint binnenkort in Pandemonium, de duistere priesters hebben alles voorbereid.\n \nWanneer het voorbij is, ben ik voornemens naar het oosten te reizen, voorbij de woestijnen van Aranoch, om mijn oudere broer te vinden die daar in een tombe gevangen zit.\n \nStap het portaal in, wij worden verwacht.|" },
};
