// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr& r )  { return r.en == 0 && r.nl == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index == 0 && r.nl == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* NL_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(NL_Ui);           return NL_Ui;
		case OVL_MENU:          *n = countRows(NL_Menu);         return NL_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(NL_UniqueItem);   return NL_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(NL_AffixPrefix);  return NL_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(NL_AffixSuffix);  return NL_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(NL_BaseItem);     return NL_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(NL_BaseName2);    return NL_BaseName2;
		case OVL_ELEMENT:       *n = countRows(NL_Element);      return NL_Element;
		case OVL_SPICIES:       *n = countRows(NL_Spicies);      return NL_Spicies;
		case OVL_ICEAGE:        *n = countRows(NL_IceAge);       return NL_IceAge;
		case OVL_SPELL:         *n = countRows(NL_Spell);        return NL_Spell;
		case OVL_SPELL_NOM:     *n = countRows(NL_SpellNom);     return NL_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(NL_PerkName);     return NL_PerkName;
		case OVL_PERK_DESC:     *n = countRows(NL_PerkDesc);     return NL_PerkDesc;
		case OVL_WARP:          *n = countRows(NL_Warp);         return NL_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* NL_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:    *n = countRows(NL_Speech);     return NL_Speech;
		case OVL_ONSCREEN:  *n = countRows(NL_OnScreen);   return NL_OnScreen;
		case OVL_QUEST:     *n = countRows(NL_Quest);      return NL_Quest;
	}
	*n = 0; return 0;
}

