// (th4) Game Changer descriptions. The "\n" breaks are structural -- the panel lays
// out title / category / body -- and are preserved one-for-one from the English.
const char* NL_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Geen (overgeslagen)";
		case 1: return "Automatisch opslaan\n\n\nVerandert de speelstijl\n\nNeemt de noodzaak weg dat de speler zelf opslaat; dat gebeurt vanzelf, net als in multiplayer.";
		case 2: return "Vaste uitrusting\n\n\nVoegt uitdaging toe\n\nMaakt het onmogelijk voorwerpen aan of af te leggen tijdens de strijd (behalve de handsleuven).";
		case 3: return "Voorwerpen vallen\n\n\nVoegt uitdaging toe\n\nBij uw dood laat u uw uitgeruste voorwerpen vallen.\n\nWaarschuwing: worden de gevallen voorwerpen niet binnen dezelfde spelsessie opgehaald, dan verdwijnen ze.";
		case 4: return "Moeiteloos\n\n\nMaakt het spel makkelijker\n\nMonsters doen u slechts halve schade.\nMakkelijker wordt het niet.";
		case 5: return "Leven van het land\n\n\nVoegt uitdaging toe\n\nStadsbewoners verkopen u geen voorwerpen.\n\nHun diensten blijven wel beschikbaar: roddel, opdrachtgesprekken, herstellen, identificeren, betoveren, maken, sleuven, herladen.";
		case 6: return "Onmogelijk\n\n\nMaakt het spel zwaarder\n\nMonsters doen u dubbele schade.\nZwaarder wordt het niet.";
		case 7: return "Drankverbod\n\n\nVoegt uitdaging toe\n\nMonsters laten niet langer willekeurig eigenschapselixers vallen\nLet op: de gave Zware drinker levert nog steeds elixers van unieke monsters";
		case 8: return "Vol contact\n\n\nMaakt het spel makkelijker\n\nMonsters met afstandsaanvallen trekken zich niet terug.";
		case 9: return "Nachtvolk\n\n\nMaakt u tot vampier\n\nU leeft en sterft door het bloed.  Uw honger is onverzadigbaar, maar u hebt alle middelen om op de zwakken te jagen\n\nDit verandert het spel.\nU gebruikt geen voorwerpen, maar vertrouwt op uw aangeboren krachten.";
		case 10: return "Hakken en slaan\n\n\nMaakt het spel makkelijker\n\nU hoeft niet langer van wapentype (scherp of stomp) te wisselen voor het monstertype.  Alle wapens doen standaardschade aan alle soorten monsters.";
		case 11: return "Ingeent\n\n\nMaakt het spel makkelijker\n\nMonsters verliezen alle immuniteiten en u hoeft niet van spreuk te wisselen - elk spreuktype werkt.\nSteenvloek, Botgeest, elementaire en heilige spreuken blijven ongewijzigd.";
		case 12: return "Dat is mijn geheim\n\n\nMaakt het spel makkelijker\n\nWoede heeft geen wachttijd en kan meteen na afloop opnieuw worden uitgesproken.";
		case 13: return "Geen herstel\n\n\nVoegt uitdaging toe\n\nHet personage heeft geen basisherstel van leven en mana.";
		case 14: return "Schone handen\n\n\nVoegt uitdaging toe\n\nMonsters laten geen voorwerpen vallen die het personage kan dragen.\nDe speler hoort ze te verkrijgen door kopen en/of betoveren.";
		case 15: return "IJstijd\n\n\nUiterlijke wijziging\n\nDe kerkerniveaus zien eruit als diepe winter, alles is bevroren en met ijs bedekt.\nHebt u zich ooit voorgesteld hoe de Hel eruit zou zien als zij bevroor?";
		case 16: return "Dag van de marmot\n\n\nVerandert de speelstijl\n\nElke keer wordt dezelfde kerker gegenereerd, met dezelfde monsters.  U kunt telkens opnieuw spelen en uw tijd verbeteren.";
		case 17: return "Taaiere monsters\n\n\nMaakt het spel zwaarder\n\nMonsters hebben +200% levenspunten.";
		case 18: return "Onvergankelijke voorwerpen\n\n\nMaakt het spel makkelijker\n\nVoorwerpen worden niet vernietigd bij nul duurzaamheid.  Zij worden onbruikbaar tot ze hersteld zijn.";
		case 19: return "Geen kaart\n\n\nVoegt uitdaging toe\n\nDe automatische kaart is niet beschikbaar\nU zult uw weg door de kerkers moeten vinden zonder haar\n\nNu al verdwaald?";
		case 20: return "Dubbele schade\n\n\nMaakt het spel makkelijker\n\nUw aanvallen doen dubbele schade aan monsters\n\nWaarschuwing: het kan teleurstellend makkelijk worden.\nKies dit niet als u de spanning van de strijd wilt behouden.";
		case 21: return "Geen kwaad zien\n\n\nVoegt uitdaging toe\n\nZien laat monsters in het duister niet oplichten.";
		case 22: return "Zwarte dood\n\n\nU bent besmet\n\nDe pest van de Zwarte Dood heeft u overgenomen.  Zij zal langzaam ernstige symptomen ontwikkelen die u uiteindelijk onvermijdelijk zullen doden.\n\nU kunt haar niet genezen, u kunt haar niet helen en u kunt haar niet stoppen.  Met de tijd wordt zij steeds erger.  Aan deze dodelijke ziekte is geen ontkomen.";
		case 23: return "Pech gehad\n\n\nVoegt uitdaging toe\n\nHet geluk raakt vroeg of laat op.  Het uwe is niet eens begonnen.\n\nU begint het spel met alle eigenschappen op 5.  U krijgt slechts 2 eigenschapspunten per niveau.  Magische vondst, verkregen ervaring en goudvondst zijn met 75% verlaagd.  U begint het spel zonder enig voorwerp.\n\nGeen gaven die u helpen met ervaring, vallende elixers, het vinden van magische voorwerpen en punten bij het stijgen van niveau.";
		case 24: return "Meedogenloos ijzer\n\n\nVoegt uitdaging toe\n\nDe klassieke Diablo Ironman was anders.\n\nEr waren geen bonuseigenschappen per niveau, geen extra ervaring, geen olien en identificaties van eindbazen.  Ook geen verbetering van de magische vondst.\n\nDeze modificator brengt u terug naar die wortels.";
		case 25: return "Versnelling\n\n\nMaakt het spel makkelijker\n\nDe ervaring is 2x verhoogd.";
		case 26: return "Ascese\n\n\nVoegt uitdaging toe\n\nHet spel wordt automatisch opgeslagen.\n\nVoorwerpen vallen bij uw dood.  U kunt niet in de stad herrijzen (u moet een nieuw spel beginnen) en daardoor gaan alle gevallen voorwerpen verloren.\n\nHet lijkt op de Hardcore-modus, maar in plaats van uw personage verliest u uw uitgeruste voorwerpen.";
		case 27: return "Terminator\n\n\nU bent een eenheid uit een serie van Cyberdyne Systems.  Model 101, infiltrerend.  De lees- en schrijfmodus van de processor is geactiveerd.  Naar het verleden gestuurd om een missie uit te voeren.\n\nHoofddoel: Uber-Diablo.\n\nTweede doel: uitroeiing van monsters.\n\nVoorwaarde: er menselijk uitzien voor de plaatselijke subjecten.\n\nDe basisverbeteringen zijn geinstalleerd.  Aanvullende verbeteringen zijn beschikbaar via zelfstudie.";
		case 28: return "Supermutant\n\n\nUw gestel kan wapens dragen die een gewoon mens doormidden zouden breken.\n\nMinigans.\n\nDingen die niet in deze wereld horen te bestaan.  U roept geen spreuken meer op.  En dat hoeft ook niet.\n\nWanneer u de trekker overhaalt, scheurt het salvo de helgebroedsels uiteen als papier in een storm.";
		case 29: return "Enclave-soldaat\n\n\nSoldaat van de Enclave-strijdkrachten, opgeleid om mutanten en genetische onzuiverheid uit te roeien.\n\nHij bevindt zich gestrand in een wereld die nooit nucleair vuur heeft gekend, maar die vuil van een andere soort kent - helgebroedsels.\n\nDe vijand is veranderd.  Het doel niet.\n\nVermogens: Beheerst energiewapens en zet gevechtsdrones in.  Bedreven in elementaire oorlogvoering.";
	}
	return nullptr;
}

