// (th4) Unique monster names. Coined names are kept AS-IS; only the descriptive
// compounds and the "X the Y" epithets are translated. Dutch compounds by direct
// CONCATENATION -- Blood+claw is simply "bloedklauw" -- so no linking vowel and no
// morpheme table with gender is needed the way Bulgarian required.
